SCENARIOS.push({
  name: '角色动作专项：380x240 立绘册面板内滚动命中',
  url: 'chrome-extension://{EXT}/popup/popup.html?play=1&ui=fancy',
  inject: false,
  run: async function (ctx) {
    var client = ctx.client;
    await reloadPet(ctx, { width: 380, height: 240 });
    await openPetBook(client);
    // 只等面板真实 CSS 打开过渡，不用 JS 假时钟猜几何位置。
    await sleep(300);
    var geometry = await petEval(client, function () {
      var panel = document.getElementById('petBook'), body = document.getElementById('petBookBody');
      var rect = panel.getBoundingClientRect();
      var out = { width: innerWidth, height: innerHeight, top: rect.top, bottom: rect.bottom,
        left: rect.left, right: rect.right, overflow: getComputedStyle(body).overflowY,
        scrollable: body.scrollHeight > body.clientHeight, pageY: scrollY };
      // 底部按钮排不许长高：fixed+left:50% 的收缩适配只看锚点右侧可用宽，窄口会把按钮
      // 压成一字宽竖排文字塔、整条带长到 88px 盖住面板中部，点击全被它拦走（批次 131）。
      var band = document.querySelector('.im-controls');
      if (band) { var bandRect = band.getBoundingClientRect(); out.bandH = Math.round(bandRect.height); out.bandW = Math.round(bandRect.width); }
      // 滚到「最后一个动作按钮」而不是滚动容器的最底 —— 面板末尾现在是成就区
      // （1.3.0 起立绘册末尾挂成就列表），滚到底看到的是成就，不再是动作按钮。
      // 最后一个是谁从 DOM 读回，不手抄键名 —— 动作库一扩充，手抄的那发就指错按钮。
      var buttons = body.querySelectorAll('.pet-book-anim:not([data-anim="random"])');
      var last = buttons[buttons.length - 1];
      var r0 = last.getBoundingClientRect(), b0 = body.getBoundingClientRect();
      // 用 rect.height（DOMRect 没有 clientHeight —— 实测踩过：undefined 混进 delta
      // 变 NaN，scrollTop += NaN 按规范静默跳过，滚动纹丝不动）
      body.scrollTop += (r0.top + r0.height / 2) - (b0.top + b0.height / 2);
      out.lastKey = last.getAttribute('data-anim');
      return out;
    });
    check('前置：CDP 确实模拟 380x240 视口', geometry.width === 380 && geometry.height === 240, JSON.stringify(geometry));
    check('短视口整块图册仍在视口内', geometry.top >= -1 && geometry.bottom <= 241 &&
      geometry.left >= -1 && geometry.right <= 381, JSON.stringify(geometry));
    check('内容在面板内部滚动，不靠整页撑高', geometry.scrollable && /auto|scroll/.test(geometry.overflow), JSON.stringify(geometry));
    check('窄视口底部按钮排保持一行横排，不许压成竖排文字塔',
      typeof geometry.bandH === 'number' && geometry.bandH > 0 && geometry.bandH <= 40,
      'band ' + geometry.bandW + 'x' + geometry.bandH);
    var hit = await petEval(client, function () {
      var body = document.getElementById('petBookBody');
      var buttons = body.querySelectorAll('.pet-book-anim:not([data-anim="random"])');
      var last = buttons[buttons.length - 1], r = last.getBoundingClientRect();
      var br = body.getBoundingClientRect(), x = r.left + r.width / 2, y = r.top + r.height / 2;
      var target = document.elementFromPoint(x, y);
      // 命中被拦时要知道是谁拦的、它自己铺在哪 —— 光看 id 定不了位（批次 131：
      // imRestorePet 在 y=136 命中而 band 理论 top≈189，两个数对不上，必须量 rect 本身）。
      var stack = document.elementsFromPoint(x, y).slice(0, 4).map(function (el) {
        var rc = el.getBoundingClientRect();
        return (el.id || el.tagName) + '@' + [rc.left, rc.top, rc.right, rc.bottom].map(Math.round).join(',');
      });
      return { key: last.getAttribute('data-anim'), x: x, y: y, scrollTop: body.scrollTop,
        pageY: scrollY, within: r.top >= br.top - 1 && r.bottom <= br.bottom + 1,
        hit: !!target && (target === last || last.contains(target)),
        hitTag: target ? target.tagName : '', hitId: target ? (target.id || target.className || '') : '',
        stack: stack };
    });
    check('最后一个动作按钮滚入面板后中心点真实命中', hit.key === geometry.lastKey && hit.scrollTop > 0 &&
      hit.within && hit.hit && hit.y >= 0 && hit.y < 240 && hit.pageY === geometry.pageY, JSON.stringify(hit));
    // 不用 DOM click 掩盖遮挡：由 CDP 在真实命中点发鼠标事件。
    await client.send('Input.dispatchMouseEvent', { type: 'mousePressed', x: hit.x, y: hit.y, button: 'left', clickCount: 1 });
    await client.send('Input.dispatchMouseEvent', { type: 'mouseReleased', x: hit.x, y: hit.y, button: 'left', clickCount: 1 });
    check('短视口最后按钮真实鼠标点击触发它自己的动作',
      await client.evaluate('document.getElementById("mascot").getAttribute("data-pose")') === hit.key);
    // 真实下限再量一次：逗玩窗口最小就是 560x440（popup.js immersiveTarget），
    // 那里带的可用宽只有 280px、仍小于按钮排自然宽，正是现场会撞上的尺寸。
    await reloadPet(ctx, { width: 560, height: 440 });
    await openPetBook(client);
    await sleep(300);
    var bandMin = await petEval(client, function () {
      var band = document.querySelector('.im-controls');
      if (!band) return null;
      var r = band.getBoundingClientRect();
      return { w: Math.round(r.width), h: Math.round(r.height), vw: innerWidth, vh: innerHeight };
    });
    check('真实最小窗口 560x440 底部按钮排同样保持一行横排',
      !!bandMin && bandMin.vw === 560 && bandMin.vh === 440 && bandMin.h > 0 && bandMin.h <= 40,
      JSON.stringify(bandMin));
  }
});

SCENARIOS.push({
  name: '角色动作专项：动态 eco / 系统减少动态效果',
  url: 'chrome-extension://{EXT}/popup/popup.html?play=1&ui=fancy',
  inject: false,
  run: async function (ctx) {
    var client = ctx.client;
    await reloadPet(ctx);
    await openPetBook(client);
    // 1.3.1 工具条只剩「玩」「藏」，WAAPI 换装改从立绘册挑图进来（pet.js 的 data-src 点击 → playMotion）。
    await petEval(client, function () {
      document.querySelector('#petBookBody [data-src]').click();
    });
    var outfitBaseline = await petEval(client, petMotionSnapshot);
    check('前置：立绘册挑图确实启动 WAAPI', outfitBaseline.mode !== 'eco' && outfitBaseline.waapi > 0,
      JSON.stringify(outfitBaseline));
    // 新序列会取消旧 WAAPI，先摸头再挑另一张图，令降档时 CSS / WAAPI / 粒子同时在场。
    await petEval(client, function () {
      document.getElementById('mascot').click();
      var cells = document.querySelectorAll('#petBookBody [data-src]');
      cells[Math.min(1, cells.length - 1)].click();
    });
    var baseline = await petEval(client, petMotionSnapshot);
    check('前置：正常模式确有角色 CSS 动画、换装 WAAPI 和摸头粒子', baseline.mode !== 'eco' &&
      baseline.role.some(function (name) { return name !== 'WAAPI'; }) && baseline.waapi > 0 && baseline.particles >= 3,
      JSON.stringify(baseline));
    // 不只在 eco 下创建新动作：先启动真实动画，再动态降档，必须清掉旧 WAAPI。
    await client.evaluate('document.documentElement.setAttribute("data-motion","eco")');
    var downgraded = await petEval(client, petMotionSnapshot);
    check('动态降到 eco 会取消已有角色 CSS / WAAPI 动画', downgraded.mode === 'eco' &&
      downgraded.role.length === 0 && downgraded.waapi === 0, JSON.stringify(downgraded));
    check('动态降到 eco 会收掉已有瞬时粒子', downgraded.particles === 0, JSON.stringify(downgraded));

    for (var pass = 0; pass < 2; pass++) {
      if (pass) await reloadPet(ctx, { reduce: true });
      var label = pass ? '系统 reduce' : '动态 eco';
      await openPetBook(client);
      var reduced = await petEval(client, function () {
        var pet = document.getElementById('mascot'), body = document.getElementById('petBookBody');
        var seen = [], violations = [], additions = [];
        var observer = new MutationObserver(function () {});
        observer.observe(document.body, { subtree: true, childList: true });
        function record(name) {
          var bad = pet.getAnimations({ subtree: true }).filter(function (a) {
            if (a.playState !== 'running' && a.playState !== 'pending') return false;
            if (!(a instanceof CSSTransition)) return true;
            var target = a.effect && a.effect.target;
            return a.transitionProperty !== 'opacity' &&
              !(a.transitionProperty === 'width' && target && target.closest('#petMood'));
          });
          if (bad.length) violations.push(name + ':' + bad.map(function (a) {
            var target = a.effect && a.effect.target;
            return (a.animationName || a.transitionProperty || 'WAAPI') + '@' +
              (target && (target.id || target.className) || '?');
          }).join(','));
        }
        // 「随机动作」抽到哪个不确定，放进逐项等值断言里必然误报，单独跳过
        Array.from(body.querySelectorAll('[data-anim]')).filter(function (button) {
          return button.getAttribute('data-anim') !== 'random';
        }).forEach(function (button) {
          button.click();
          seen.push([button.getAttribute('data-anim'), pet.getAttribute('data-pose')]);
          record(button.getAttribute('data-anim'));
        });
        // 换装在低动态下同样走册子（工具条只剩「玩」「藏」）：挑一张图，同样只许静态提示。
        var srcCell = body.querySelector('[data-src]');
        if (srcCell) { srcCell.click(); record('outfit'); }
        pet.click(); record('pet');
        observer.takeRecords().forEach(function (mutation) {
          Array.from(mutation.addedNodes).forEach(function (node) {
            if (node.nodeType === 1 && (node.matches('.fx-heart,.fx-ripple,.fx-spark,.fx-snow,.fx-leaf') ||
              node.querySelector('.fx-heart,.fx-ripple,.fx-spark,.fx-snow,.fx-leaf'))) additions.push(node.className);
          });
        });
        observer.disconnect();
        return { seen: seen, violations: violations, additions: additions,
          reduce: matchMedia('(prefers-reduced-motion: reduce)').matches,
          mode: document.documentElement.getAttribute('data-motion'), transition: pet.style.transition,
          particles: document.querySelectorAll('.fx-heart,.fx-ripple,.fx-spark,.fx-snow,.fx-leaf').length };
      });
      check(label + '：设置真实生效且 15 动作按钮仍然能切换静态姿态', reduced.mode === 'eco' &&
        reduced.reduce === !!pass && reduced.seen.length === 15 &&
        reduced.seen.every(function (pair) { return pair[0] === pair[1]; }), JSON.stringify(reduced));
      check(label + '：动作 / 换装 / 摸头均无角色 CSS 或 WAAPI 动画',
        reduced.violations.length === 0 && !/translate|transform/.test(reduced.transition), JSON.stringify(reduced));
      check(label + '：同套点击不生成瞬时粒子（包含创建后立即移除）',
        reduced.additions.length === 0 && reduced.particles === 0, JSON.stringify(reduced));
      var quiet = await petEval(client, petMotionSnapshot);
      check(label + '：常驻季节粒子也没有运行中的动画', quiet.ambient === 0, JSON.stringify(quiet));
    }
    check('低动态专项全程无未捕获异常', client.errors().length === 0, client.errors().join(' | '));
  }
});

// 交互回归：连点「玩」不能误判为"戳她"；「藏」与「让她回来」必须闭环。
SCENARIOS.push({
  name: '弹窗前端：连点「玩」不误判 / 藏与让她回来闭环',
  url: 'chrome-extension://{EXT}/popup/popup.html?play=1&ui=fancy',
  inject: false,
  run: async function (ctx) {
    var r = await ctx.client.evaluate(
      '(async function(){' +
      'await new Promise(function(r){setTimeout(r,1600);});' +
      'var pet=document.getElementById("mascot");' +
      'if(!pet) return {ok:false};' +
      'pet.classList.add("show");' +
      'var out={ok:true};' +
      'var b=document.querySelector("#petTools button[data-act=\\"game\\"]");' +
      'if(b){b.click();b.click();b.click();}' +
      'await new Promise(function(r){setTimeout(r,200);});' +
      'out.dodged=pet.classList.contains("dodge");' +
      // ⚠️ 上面那枚 class **生产里从来没往人身上加**（`popup/pet.js` 只有 remove），所以它单独是个空信号。
      // 真信号是这一族演的那个姿态与那句台词的归因 —— 三个「玩」点下去既不该 shake 也不该说 dodge 那一族。
      'out.afterToolsPose=pet.getAttribute("data-pose");' +
      'out.afterToolsFrom=pet.getAttribute("data-say-from");' +
      'if(b){b.dispatchEvent(new PointerEvent("pointerdown",{bubbles:true,pointerId:2,button:0,isPrimary:true,clientX:b.getBoundingClientRect().left+5,clientY:b.getBoundingClientRect().top+5}));}' +
      'out.dragFromTools=pet.classList.contains("dragging");' +
      'var h=document.querySelector("#petTools button[data-act=\\"hide\\"]");' +
      'if(h)h.click();' +
      'await new Promise(function(r){setTimeout(r,150);});' +
      'out.hidden=pet.style.display==="none";' +
      // 「藏」的**持久化**没人守过：以前这条断言写的是 `r.hidAfterHide || r.hidden`，
      // 而 `hidAfterHide` 这个字段探针从来没写过 —— 左半边是死的，等于只断了"这一下收起来了"。
      // 「下次打开弹窗还藏着」靠的是 localStorage 那个键（popup/pet.js:350 HIDE_KEY）。
      'out.hideStored=localStorage.getItem("omitone.pet.hidden");' +
      // 1.3.1 起「显示小人」入口在窗口底部那排（#imRestorePet），弹窗里的按钮已拆。
      'var sp=document.getElementById("imRestorePet");' +
      'out.hasShowBtn=!!sp;' +
      'if(sp)sp.click();' +
      'await new Promise(function(r){setTimeout(r,200);});' +
      'out.shown=pet.style.display!=="none"&&pet.classList.contains("show");' +
      'out.hideCleared=localStorage.getItem("omitone.pet.hidden");' +
      // 归因格的"不写死"证明：同一条通道在 dodge 那一族上必须读出 dodge。
      // 只钉 moodHigh 是不够的 —— 实现里把名字写成常量，那一条照样绿。
      'pet.click();pet.click();pet.click();' +
      'await new Promise(function(r2){setTimeout(r2,260);});' +
      'out.triple={pose:pet.getAttribute("data-pose"),from:pet.getAttribute("data-say-from"),' +
      'said:pet.getAttribute("data-say-line"),line:document.getElementById("mascotBubble").textContent,' +
      'show:document.getElementById("mascotBubble").classList.contains("show")};' +
      'return out;})()'
    );
    check('连点「玩」三次不会被当成戳（不躲）', !!r && r.ok && r.dodged === false &&
      r.afterToolsPose !== 'shake' && r.afterToolsFrom !== 'dodge', JSON.stringify(r));
    // 与下面 moodHigh 那一格配对：同一条归因通道在两个族上读出两个不同的名字，
    // 实现里把名字写死成一个常量就当场红一条（只钉一族是拦不住的）。
    check('连戳她三下真的躲开，且那句归因到 dodge 一族（归因格与气泡同源）',
      !!r && r.triple && r.triple.pose === 'shake' && r.triple.from === 'dodge' &&
      r.triple.show === true && r.triple.line.length > 0 && r.triple.line === r.triple.said,
      JSON.stringify(r && r.triple));
    check('「藏」能把人收起来，并把"藏着"写进存档（下次打开弹窗还在藏着的状态）',
      !!r && r.hidden === true && r.hideStored === '1', JSON.stringify(r));
    check('点「让她回来」能重新出现，并清掉存档里的"藏着"',
      !!r && r.shown === true && (r.hideCleared === null || r.hideCleared === '0'), JSON.stringify(r));
    check('按在工具条上不会启动拖动（否则 click 被重定向成"戳"）', !!r && r.dragFromTools === false, JSON.stringify(r));
  }
});


// ══════════════════════════════════════════════════════════════════════
// 前端专项（一）：弹窗全功能自检
// 上一版只"点了按钮"，没验证"按钮点不点得到" —— 所以"被遮住/看不见"
// 这类问题全漏了。这里用 elementFromPoint 做**命中测试**：命中点必须是
// 按钮自己，才算真的可点。
// ══════════════════════════════════════════════════════════════════════
SCENARIOS.push({
  name: '弹窗前端：全功能自检（含命中测试）',
  url: 'chrome-extension://{EXT}/popup/popup.html?play=1&ui=fancy',
  inject: false,
  run: async function (ctx) {
    var r = await ctx.client.evaluate(
      '(async function(){' +
      'var out={errs:[]};window.addEventListener("error",function(e){out.errs.push(String(e.message));});' +
      'await new Promise(function(r){setTimeout(r,1500);});' +
      'var pet=document.getElementById("mascot");' +
      'out.petShown=!!(pet&&pet.classList.contains("show"));' +
      'out.ui=document.documentElement.getAttribute("data-ui");' +
      // —— 命中测试：按钮的中心点，elementFromPoint 必须命中按钮自己 ——
      // 1.3.1 起她身上只剩「玩」「藏」两枚（换装/表情/姿势收进立绘册与随机）。
      'var vp={w:innerWidth,h:innerHeight};out.vp=vp;' +
      'var tools=document.getElementById("petTools");' +
      'out.toolsRect=(function(){if(!tools)return "noEl";var t=tools.getBoundingClientRect();' +
      '  return Math.round(t.left)+","+Math.round(t.top)+","+Math.round(t.width)+"x"+Math.round(t.height);})();' +
      'out.petRect=(function(){if(!pet)return "noEl";var p=pet.getBoundingClientRect();' +
      '  return Math.round(p.left)+","+Math.round(p.top)+","+Math.round(p.width)+"x"+Math.round(p.height);})();' +
      'var hits={},rects={};["game","hide"].forEach(function(a){' +
      '  var b=document.querySelector("#petTools button[data-act=\\""+a+"\\"]");' +
      '  if(!b){hits[a]="missing";rects[a]="noEl";return;}' +
      '  var rc=b.getBoundingClientRect();' +
      '  var cx=rc.left+rc.width/2, cy=rc.top+rc.height/2;' +
      '  var el=document.elementFromPoint(cx,cy);' +
      '  hits[a]=(el===b||(el&&b.contains(el)));' +
      '  rects[a]=Math.round(rc.left)+","+Math.round(rc.top)+","+Math.round(rc.width)+"x"+Math.round(rc.height)' +
      "    +\"@\"+Math.round(cx)+\"/\"+Math.round(cy)+' inView='+(cx>=0&&cy>=0&&cx<vp.w&&cy<vp.h)" +
      "    +\" hit=\"+(el?String(el.tagName)+'#'+el.id+'.'+String(el.className).slice(0,24):'null');" +
      '});' +
      'out.hits=hits;out.rects=rects;' +
      // —— 拖动（放在点击之前，避免姿态/换装干扰位置）——
      'function ev(t,x,y){return new PointerEvent(t,{bubbles:true,pointerId:1,button:0,isPrimary:true,clientX:x,clientY:y});}' +
      'var d0=pet.getBoundingClientRect();' +
      'pet.dispatchEvent(ev("pointerdown",d0.left+12,d0.top+12));' +
      'pet.dispatchEvent(ev("pointermove",d0.left-70,d0.top+40));' +
      'pet.dispatchEvent(ev("pointerup",d0.left-70,d0.top+40));' +
      'await new Promise(function(r){setTimeout(r,350);});' +
      'var d1=pet.getBoundingClientRect();' +
      'out.dragDx=Math.round(d1.left-d0.left);' +
      'out.inView=d1.left>=-1&&d1.right<=innerWidth+1&&d1.top>=-1;' +
      // —— 隐藏（放最后）：这一次点击只为「全程无未捕获异常」走一遍那条路径 ——
      'var bh=document.querySelector("#petTools button[data-act=\\"hide\\"]");' +
      'if(bh)bh.click();await new Promise(function(r){setTimeout(r,150);});' +
      'out.errCount=out.errs.length;out.errText=out.errs.join(" | ");' +
      'return out;})()'
    );
    check('角色在精美模式下自动出现', !!r && r.petShown === true, JSON.stringify({shown: r && r.petShown, ui: r && r.ui}));
    var hitInfo = JSON.stringify({hits: r && r.hits, rects: r && r.rects, vp: r && r.vp, toolsRect: r && r.toolsRect, petRect: r && r.petRect});
    check('「玩」按钮真的点得到（命中测试）', !!r && r.hits && r.hits.game === true, hitInfo);
    check('「藏」按钮真的点得到（命中测试）', !!r && r.hits && r.hits.hide === true, hitInfo);
    // 这一场只测**命中测试 + 拖动**这一层；「点「玩」开小游戏」「点「藏」收起」
    // 的行为断言分别在「小游戏摸头涨好感」与「连点「玩」不误判 / 藏与让她回来闭环」
    // 那两场里（同分支、同层、同夹具的重复这里不再背一份）。
    // 上面那两次点击仍然保留：「全程无未捕获异常」要各自真走一遍那条路径。
    check('拖动位移 > 30px', !!r && Math.abs(r.dragDx) > 30, r ? String(r.dragDx) : '');
    check('拖完仍在视口内', !!r && r.inView === true, '');
    check('全程无未捕获异常', !!r && r.errCount === 0, r ? r.errText : '');
  }
});

// ══════════════════════════════════════════════════════════════════════
// 前端专项（二）：沉浸式窗口应当只剩吉祥物
// 之前 ?play=1 只改了窗口尺寸、从没加 .im 类，打开就是放大版设置面板。
// ══════════════════════════════════════════════════════════════════════
SCENARIOS.push({
  name: '沉浸式窗口：只剩吉祥物',
  url: 'chrome-extension://{EXT}/popup/popup.html?play=1&ui=fancy',
  inject: false,
  run: async function (ctx) {
    // ⚠️ 窗口原尺寸必须在**任何一次改尺寸之前**捕获。
    // 下面「带 w/h 打开」那两条断言会让页面自己 chrome.windows.update 到 620x470 ——
    // 等它做完再读"原尺寸"，读到的就是 620x470，收尾"还原"还原的是这个泄漏值，
    // 于是下一场景（弹窗开关那族）在 470 高的视口里点 y≈519 那一格，
    // elementFromPoint 返回 null → 前提红 → 整族 6 条连坐（全量实测踩过）。
    var orig = null;
    try {
      orig = await ctx.client.evaluate('(async function(){' +
        'var w=await chrome.windows.getCurrent();' +
        'return {id:w.id,left:w.left,top:w.top,width:w.width,height:w.height};})()');
    } catch (e) { orig = null; }

    var r = await ctx.client.evaluate(
      '(async function(){' +
      'await new Promise(function(r){setTimeout(r,1200);});' +
      'var out={};' +
      'out.imClass=document.body.classList.contains("im");' +
      'out.imHtml=document.documentElement.classList.contains("im");' +
      // 用「量不量得到」判隐藏，不用 display 计算值 —— 现在藏的是祖先
      // （.container 整条被藏），子节点自己的 display 照样是 flex/block。
      'var top=document.querySelector(".top");' +
      'out.topPainted=!!(top&&top.getClientRects().length);' +
      // 1.3.1 起小游戏/聊天/体检三块面板也是 body 的直接孩子（display:flex 但 opacity:0 挂着，
      // .show 才露脸）—— 量得到矩形不算"漏网"，它们与立绘册同属"我们的面板"。
      'var keep={fxLayer:1,mascot:1,petBook:1,petGame:1,petChat:1,petDiag:1,toast:1};' +
      'out.strays=Array.prototype.slice.call(document.body.children).filter(function(el){' +
      ' var b=el.getBoundingClientRect();' +
      ' return !keep[el.id] && !el.classList.contains("im-controls") && b.width>0 && b.height>0;' +
      ' }).map(function(el){return el.tagName+"#"+(el.id||"-");});' +
      'var pet=document.getElementById("mascot");' +
      'out.petVisible=pet?getComputedStyle(pet).display!=="none":null;' +
      'return out;})()'
    );
    check('body 与 html 都带上了 .im 类（html 那条要盖掉 356px 的弹窗定宽）',
      !!r && r.imClass === true && r.imHtml === true, JSON.stringify(r));
    check('设置面板不再参与布局（整棵子树一个矩形都量不到）', !!r && r.topPainted === false, JSON.stringify(r));
    check('body 底下除角色/粒子/立绘册/提示条/控制条之外没有第二样东西还露着',
      !!r && Array.isArray(r.strays) && r.strays.length === 0, JSON.stringify(r));
    check('吉祥物仍然显示', !!r && r.petVisible === true, JSON.stringify(r));

    // ── 「展开」的开窗尺寸 ──────────────────────────────────────────────
    // chrome.windows.create 里的 width/height 会被 Edge 记住的旧位置**整个忽略**
    //（现场实测：请求 760x680，开出来 1400x900）。真正认账的是新窗口自己
    // 按 URL 上的 w/h 补的那一发 chrome.windows.update —— 所以这里换一个
    // 带尺寸的 search 重新加载，量窗口有没有真落到那一档。
    try {
      await ctx.client.evaluate('(async function(){ location.search="play=1&ui=fancy&w=620&h=470"; return 1; })()');
    } catch (e) { /* 导航会把执行上下文掀掉，这条 rejection 是预期内的 */ }
    var fitted = null;
    var fitStarted = Date.now();
    var FIT_READ = '(async function(){' +
      'var w=await chrome.windows.getCurrent();' +
      'return {ready:document.readyState,href:String(location.href).slice(-46),winId:w.id,state:w.state,' +
      'win:{w:w.width,h:w.height},inner:{w:window.innerWidth,h:window.innerHeight}};})()';
    for (var f = 0; f < 24; f++) {
      await sleep(250);
      try {
        fitted = await ctx.client.evaluate(FIT_READ);
      } catch (e) { fitted = null; continue; }
      if (fitted && fitted.ready === "complete" && Math.abs(fitted.win.w - 620) <= 10) break;
    }
    // ⚠️ 轮询到点而尺寸没动时，「机器把人饿住了」与「窗口管理侧接了但不认」在同一条取证里长一样。
    // 判据一个字不动，只多读一次：再等 5 秒，late 动到了 = 慢；late 还在原位 = 不是慢。
    fitted = fitted || {};
    fitted.waitedMs = Date.now() - fitStarted;
    if (fitted.win && Math.abs(fitted.win.w - 620) > 10) {
      await sleep(5000);
      try {
        var lateRead = await ctx.client.evaluate(FIT_READ);
        fitted.late = lateRead && lateRead.win;
        fitted.lateState = lateRead && lateRead.state;
      } catch (e) { fitted.late = 'read-throw'; }
    }
    check('带 w/h 打开时窗口自己拉到那一档（不是 create 那一发被忽略就完事）',
      !!fitted.win && Math.abs(fitted.win.w - 620) <= 10 && Math.abs(fitted.win.h - 470) <= 10,
      JSON.stringify({ target: { w: 620, h: 470 }, got: fitted }));
    check('拉完之后文档根仍然跟着视口（尺寸是自己算的，不是猜的）',
      !!fitted && fitted.ready === "complete" && Math.abs(fitted.inner.w - fitted.win.w) <= 24,
      JSON.stringify(fitted));

    // ── 沉浸式几何（批次 62）──────────────────────────────────────────
    // 现场量到的形状（CDP 9334，用户那台 1.5 倍缩放的机器）：
    //   1400x900 那档 -> 文档根仍然只有 **356px** 宽，右边 **1030px** 是空的背景；
    //   拉到 760x680 -> 空白 390px，底部居中的控制条压进那 356 列 **80px**；
    //   拉到 420x380 -> 控制条整条 179px 落进列里，还和角色重叠 **41x27**。
    // 根因是 `html{width:356px}`（popup.html 给扩展弹窗定尺寸的那条）在沉浸式里没人覆盖，
    // 而控制条 / 角色是 `position:fixed`，按**视口**排 —— 两套坐标系并存在同一个页面上。
    // 所以这里量的是**关系**（谁跟谁重叠、根元素跟不跟视口一致），不是像素审美。
    var GEOM = '(async function(){' +
      'function rc(el){ if(!el) return null; var b=el.getBoundingClientRect();' +
      ' return {x:Math.round(b.left),y:Math.round(b.top),w:Math.round(b.width),h:Math.round(b.height),r:Math.round(b.right),b:Math.round(b.bottom)}; }' +
      'function hit(a,b){ if(!a||!b) return null;' +
      ' var w=Math.min(a.r,b.r)-Math.max(a.x,b.x), h=Math.min(a.b,b.b)-Math.max(a.y,b.y);' +
      ' return (w>0&&h>0)?{w:w,h:h}:null; }' +
      'var html=rc(document.documentElement), body=rc(document.body);' +
      'var ctrl=rc(document.querySelector(".im-controls"));' +
      'var pet=rc(document.getElementById("mascot"));' +
      'var winState="?", winId=null;' +
      'try{var cw=await chrome.windows.getCurrent();winState=cw.state;winId=cw.id;}' +
      'catch(e){winState="read-throw:"+String(e&&e.message||e).slice(0,40);}' +
      'return {inner:{w:window.innerWidth,h:window.innerHeight},htmlW:html?html.w:null,bodyW:body?body.w:null,' +
      ' winState:winState,winId:winId,' +
      ' ctrl:ctrl,pet:pet,overCtrlPet:hit(ctrl,pet),overCtrlHtml:hit(ctrl,html),' +
      ' inView:!!(ctrl&&ctrl.x>=0&&ctrl.r<=window.innerWidth&&ctrl.b<=window.innerHeight),' +
      ' scroll:{sw:document.documentElement.scrollWidth,sh:document.documentElement.scrollHeight},' +
      ' tall:Array.prototype.slice.call(document.querySelectorAll("body *")).filter(function(el){' +
      '   var b=el.getBoundingClientRect(); return b.height>0&&b.bottom>window.innerHeight+1;' +
      ' }).slice(0,10).map(function(el){var b=el.getBoundingClientRect();var c=getComputedStyle(el);' +
      '   return el.tagName+"."+String(el.className).split(" ")[0]+" b="+Math.round(b.bottom)+" pos="+c.position+" top="+c.top+" h="+c.height;}) ,' +
      ' kids:Array.prototype.slice.call(document.body.children).map(function(el){var b=el.getBoundingClientRect();' +
      '   return el.tagName+"#"+(el.id||"-")+"."+(String(el.className).split(" ")[0]||"-")' +
      '     +" disp="+getComputedStyle(el).display+" b="+Math.round(b.bottom);}) };})()';

    // 现场（1400x900 / 760x680 / 420x380）三档都量过；沙盒这一档只能到 520x400 ——
    // 普通标签窗口的最小宽度把 420 顶成 inner 493，那条「夹具自证」会正确报红，
    // 所以沙盒取**它自己拉得动**的最窄一档，420x380 那组数字留在上面的注释里当现场证据。
    var SIZES = [{ w: 760, h: 680 }, { w: 520, h: 400 }];
    // orig 已在 run 开头捕获（见那里那条⚠️），这里只许用，不许重新读一遍

    for (var i = 0; i < SIZES.length; i++) {
      var size = SIZES[i];
      var tag = size.w + 'x' + size.h;
      var updStarted = Date.now();
      // 这一发是本场景**自己**改窗口尺寸（不经 popup.js）—— 它要是没拉动，就说明根因不在页面那侧。
      // 成败必须读得回来：rejected 与 resolved-but-no-effect 是两件事，以前两条都长得像"没跑到那一档"。
      var upd = 'eval-throw';
      try {
        upd = await ctx.client.evaluate('(async function(){' +
          'var w=await chrome.windows.getCurrent();' +
          'try { await chrome.windows.update(w.id,{left:40,top:40,width:' + size.w + ',height:' + size.h + '}); return "resolved"; }' +
          'catch (e) { return "rejected:" + String(e && e.message || e).slice(0, 90); }' +
          '})()');
      } catch (e) { upd = 'eval-throw'; }
      // 轮询到视口稳定，别猜毫秒（缩放/重排是异步的）
      var g = null, last = '';
      for (var k = 0; k < 20; k++) {
        await sleep(250);
        g = await ctx.client.evaluate(GEOM);
        var now = JSON.stringify(g && g.inner);
        if (now === last && g && g.ctrl) break;
        last = now;
      }
      var dw = g && g.inner ? Math.abs(g.inner.w - size.w) : -1;
      var gEv = g && { inner: g.inner, winState: g.winState, winId: g.winId };
      check(tag + '：**夹具自证** —— 窗口真的被拉到了这一档（视口与请求宽之差必须 ≤40，覆盖窗口装饰）',
        dw >= 0 && dw <= 40, JSON.stringify({
          requested: size, inner: g && g.inner, deltaW: dw,
          // upd=resolved 而尺寸不动 = 窗口管理侧接了不认；state 不是 normal 就是它自己给的口供
          upd: upd, waitedMs: Date.now() - updStarted, got: gEv }));
      check(tag + '：文档根跟随视口宽度，不许把沉浸式留成一条 356px 的弹窗列',
        !!g && g.htmlW === g.inner.w && g.bodyW === g.inner.w, JSON.stringify(g && { inner: g.inner, htmlW: g.htmlW, bodyW: g.bodyW }));
      check(tag + '：底部控制条整条在视口内', !!g && g.inView === true, JSON.stringify(g && { inner: g.inner, ctrl: g.ctrl }));
      check(tag + '：控制条不与角色重叠（角色压住按钮就点不着了）',
        !!g && g.overCtrlPet === null, JSON.stringify(g && { ctrl: g.ctrl, pet: g.pet, over: g.overCtrlPet }));
      check(tag + '：沉浸式页面没有幻影滚动（ scrollWidth/Height 不许超出视口）',
        !!g && g.scroll.sw <= g.inner.w && g.scroll.sh <= g.inner.h, JSON.stringify(g && { inner: g.inner, scroll: g.scroll, tall: g.tall, kids: g.kids }));
    }

    // 拖到底也不许压住控制条 —— 走**真指针事件**，让生产的钳位逻辑自己算，不在测试里重算一遍
    await ctx.client.evaluate('(async function(){' +
      'var w=await chrome.windows.getCurrent();' +
      'await chrome.windows.update(w.id,{left:40,top:40,width:520,height:400});return 1;})()');
    await sleep(600);
    var drag = await ctx.client.evaluate('(async function(){' +
      'var pet=document.getElementById("mascot");' +
      'var b=pet.getBoundingClientRect();' +
      'var sx=b.left+b.width/2, sy=b.top+20;' +
      'function fire(t,x,y){ pet.dispatchEvent(new PointerEvent(t,{bubbles:true,cancelable:true,pointerId:1,isPrimary:true,clientX:x,clientY:y,pointerType:"mouse"})); }' +
      'fire("pointerdown",sx,sy);' +
      'for(var i=1;i<=6;i++){ fire("pointermove",sx,sy+i*30); await new Promise(function(r){setTimeout(r,40);}); }' +
      'fire("pointermove",60,window.innerHeight-6); await new Promise(function(r){setTimeout(r,40);});' +
      'fire("pointerup",60,window.innerHeight-6);' +
      'await new Promise(function(r){setTimeout(r,300);});' +
      'function rc(el){var q=el.getBoundingClientRect();return{x:Math.round(q.left),y:Math.round(q.top),w:Math.round(q.width),h:Math.round(q.height),r:Math.round(q.right),b:Math.round(q.bottom)};}' +
      'var p=rc(document.getElementById("mascot")), c=rc(document.querySelector(".im-controls"));' +
      'var ovW=Math.min(p.r,c.r)-Math.max(p.x,c.x), ovH=Math.min(p.b,c.b)-Math.max(p.y,c.y);' +
      'var inView=p.x>=0&&p.r<=window.innerWidth&&p.b<=window.innerHeight;' +
      'return {pet:p,ctrl:c,over:(ovW>0&&ovH>0)?{w:ovW,h:ovH}:null,inView:inView,inner:{w:window.innerWidth,h:window.innerHeight}};})()');
    check('把角色拖到最底：仍然不压住控制条，且整只留在视口内',
      !!drag && drag.over === null && drag.inView === true, JSON.stringify(drag));

    if (orig && orig.id) {
      try {
        await ctx.client.evaluate('(async function(){' +
          'await chrome.windows.update(' + orig.id + ',{left:' + (orig.left || 0) + ',top:' + (orig.top || 0) +
          ',width:' + orig.width + ',height:' + orig.height + '});return 1;})()');
      } catch (e) { /* 收尾失败不影响结论，下面那条会量回来 */ }
      var restored = null;
      for (var z = 0; z < 12; z++) {
        await sleep(200);
        try {
          restored = await ctx.client.evaluate('(async function(){' +
            'var w=await chrome.windows.getCurrent();' +
            'return {w:w.width,h:w.height,innerH:window.innerHeight};})()');
        } catch (e) { restored = null; continue; }
        if (restored && Math.abs(restored.w - orig.width) <= 2 && Math.abs(restored.h - orig.height) <= 2) break;
      }
      // 这条是**量回来的**，不是"发了 update 就算还原"。上一轮就是因为还原值取错了基线，
      // 把窗口留在 620x470，下一族弹窗开关点 y≈519 直接掉到视口外，连红 6 条。
      check('收尾：窗口真的还回了进来时那一档（尺寸不许泄漏给下一个场景）',
        !!restored && Math.abs(restored.w - orig.width) <= 2 && Math.abs(restored.h - orig.height) <= 2,
        JSON.stringify({ orig: { w: orig.width, h: orig.height }, got: restored }));
    } else {
      check('前提：窗口原尺寸在动任何尺寸之前就读到了（读不到就没有"还原"这回事）',
        false, JSON.stringify(orig));
    }
  }
});




// ── 前端专项：设置页不再画她（1.3.1 起角色只在逗玩窗口与刷课页现身） ─────────
// 设置页是"控制中心"：等级/好感状态行 + 四枚入口按钮（深链进逗玩窗口对应面板）。
// 这里断三层：JS 出场判过 body.im；CSS 兜底 body:not(.im) #mascot 恒藏；
// lite 模式连状态行与入口一起收。哪天有人在设置页把她画回来，三条至少红一条。
SCENARIOS.push({
  name: '设置页不再画她：角色本体隐藏、入口齐全；lite 连状态行一起收',
  url: 'chrome-extension://{EXT}/popup/popup.html?ui=fancy',
  inject: false,
  run: async function (ctx) {
    var client = ctx.client;
    // 先抄走好感存档，种一份最小档（affection:5）—— 没存档时 renderBond 直接折返，
    // 状态行停在出厂占位话，那条断言就会随场景顺序翻红。收尾原样放回。
    var savedBond = JSON.parse(await client.evaluate(
      'new Promise(function(res){chrome.storage.local.get("omitonePetBond",' +
      'function(r){res(JSON.stringify(r||{}))})})'));
    await client.evaluate('new Promise(function(res){chrome.storage.local.set(' +
      JSON.stringify({ omitonePetBond: { affection: 5 } }) + ',function(){res(true)})})');
    // 清掉角色自己的 localStorage 键（藏着/坐标/装束），再重载 —— 让「本体恒藏」
    // 这条断言走的是 CSS 兜底那条路，而不是上一次场景留下的内联 important 藏。
    await client.evaluate('(function(){["omitone.pet.hidden","omitone.pet.pos","omitone.pet.pos.im",' +
      '"omitone.pet.src","omitone.pet.outfit","omitone.pet.face","omitone.pet.mood","omitone.pet.night"]' +
      '.forEach(function(k){localStorage.removeItem(k);});return 1;})()');
    try { await client.evaluate('location.reload()'); } catch (e) { /* 导航掀掉执行上下文是预期内的 */ }
    await waitFor(client, 'document.readyState === "complete"', 10000);
    await sleep(800);
    var fancy = await client.evaluate(
      '(function(){var pet=document.getElementById("mascot");' +
      'var ids=["btnExpand","btnPetBook","btnPetChat","btnPetDiag","petStatus"];' +
      'var missing=ids.filter(function(id){return !document.getElementById(id);});' +
      'return {display:pet?getComputedStyle(pet).display:"(no el)",' +
      'rects:pet?pet.getClientRects().length:-1,' +
      'status:document.getElementById("petStatus")?document.getElementById("petStatus").textContent:"",'+
      'missing:missing};})()'
    );
    check('设置页（fancy）里她的本体恒藏（JS 出场判 + CSS 兜底各占一半）',
      fancy.display === 'none' && fancy.rects === 0, JSON.stringify(fancy));
    check('设置页「吉祥物」栏四枚入口与状态行都在（打开逗玩窗口/看立绘册/和她聊天/本地体检）',
      fancy.missing.length === 0, JSON.stringify(fancy.missing));
    check('状态行由 renderBond 填出等级与好感（不再是出厂占位话）',
      /好感/.test(fancy.status) && fancy.status.indexOf('还没读到她的存档') === -1, fancy.status);

    // lite 模式：pet.js 第一行就折返，入口与状态行由 popup.html 的 lite 规则收掉。
    try { await client.evaluate('location.search = "ui=lite"'); } catch (e) { /* 预期：导航掀掉上下文 */ }
    await waitFor(client, 'document.readyState === "complete" && document.documentElement.getAttribute("data-ui") === "lite"', 10000);
    await sleep(400);
    var lite = await client.evaluate(
      '(function(){var g=function(id){var el=document.getElementById(id);return el?getComputedStyle(el).display:"(no el)";};' +
      'return {expand:g("btnExpand"),book:g("btnPetBook"),chat:g("btnPetChat"),diag:g("btnPetDiag"),' +
      'status:g("petStatus"),mascot:g("mascot")};})()'
    );
    check('lite 模式：四枚入口与状态行 display:none，角色本体也不画',
      lite.expand === 'none' && lite.book === 'none' && lite.chat === 'none' && lite.diag === 'none' &&
      lite.status === 'none' && lite.mascot === 'none', JSON.stringify(lite));

    // 收尾：好感存档原样放回（原来就没有就摘掉，不许写 undefined 进去）。
    if (savedBond.omitonePetBond !== undefined) {
      await client.evaluate('new Promise(function(res){chrome.storage.local.set(' +
        JSON.stringify({ omitonePetBond: savedBond.omitonePetBond }) + ',function(){res(true)})})');
    } else {
      await client.evaluate('new Promise(function(res){chrome.storage.local.remove("omitonePetBond",function(){res(true)})})');
    }
    check('设置页专项全程无未捕获异常', client.errors().length === 0, client.errors().join(' | '));
  }
});

// ── 前端专项：角色控件"点了要有反应" ──────────────────────────────────────
// 这类 bug（点了没反应、装扮没换）**不会抛异常**，只能靠"点完之后状态变了没有"来抓。
// 以后新增任何角色控件，都在这里补一条断言。
SCENARIOS.push({
  name: '弹窗前端：角色控件点一遍都要有反应',
  url: 'chrome-extension://{EXT}/popup/popup.html?play=1&ui=fancy',
  inject: false,
  run: async function (ctx) {
    var r = await ctx.client.evaluate(
      '(async function(){' +
      'var out={errs:[]};' +
      'window.addEventListener("error",function(e){out.errs.push(String(e.message));});' +
      'await new Promise(function(r){setTimeout(r,1200);});' +
      'var pet=document.getElementById("mascot");' +
      'var img=pet&&pet.querySelector(".pet-art");' +
      'out.hasPet=!!pet;out.src0=img?img.getAttribute("src"):"";' +
      // 1.3.1 起换装/换姿势的入口是立绘册（imBook 开门，册子里挑图 / 点动作），
      // 工具条只剩「玩」「藏」两枚。
      'var ib=document.getElementById("imBook");' +
      'if(ib){ib.click();await new Promise(function(r){setTimeout(r,180);});}' +
      'out.bookOpen=document.getElementById("petBook")&&document.getElementById("petBook").getAttribute("aria-hidden")==="false";' +
      'var cell=null;' +
      'Array.prototype.forEach.call(document.querySelectorAll("#petBookBody [data-src]"),function(c){' +
      '  if(!cell&&c.getAttribute("data-src")!==out.src0)cell=c;});' +
      'if(cell){cell.click();await new Promise(function(r){setTimeout(r,180);});}' +
      'out.src1=img?img.getAttribute("src"):"";' +
      'out.poseAttr0=pet?pet.getAttribute("data-pose"):"";' +
      'var ab=document.querySelector("#petBookBody [data-anim]:not([data-anim=\\"random\\"])");' +
      'out.animKey=ab?ab.getAttribute("data-anim"):"";' +
      'if(ab){ab.click();await new Promise(function(r){setTimeout(r,180);});}' +
      'out.poseAttr=pet?pet.getAttribute("data-pose"):"";' +
      'if(ib){ib.click();await new Promise(function(r){setTimeout(r,150);});}' +
      'var h=document.querySelector("#petTools button[data-act=\\"hide\\"]");' +
      'if(h){h.click();await new Promise(function(r){setTimeout(r,140);});}' +
      'out.hidden=pet?pet.style.display==="none":null;' +
      'var sp=document.getElementById("imRestorePet");' +
      'if(sp){sp.click();await new Promise(function(r){setTimeout(r,140);});}' +
      'out.shown=pet?pet.style.display!=="none":null;' +
      'document.querySelectorAll(".toggle").forEach(function(t){t.click();t.click();});' +
      'await new Promise(function(r){setTimeout(r,220);});' +
      'out.errCount=out.errs.length;out.errText=out.errs.join(" | ");' +
      'return out;})()'
    );
    check('前置：弹窗里有角色元件', !!r && r.hasPet === true, JSON.stringify(r));
    check('前置：立绘册真的开了（imBook 开门，不是直接改 DOM）', !!r && r.bookOpen === true, JSON.stringify(r));
    check('册子里挑一张图真的换立绘（不是只变色）', !!r && r.src0 !== r.src1, r ? r.src0 + ' → ' + r.src1 : '');
    check('册子里点一个动作真的换了 CSS 姿态（动作键就是姿态名）',
      !!r && typeof r.animKey === 'string' && r.animKey !== '' && r.animKey !== 'random' && r.poseAttr === r.animKey,
      r ? r.poseAttr0 + ' → ' + r.poseAttr + '（点了 ' + r.animKey + '）' : '');
    check('点「藏」会收起来', !!r && r.hidden === true, '');
    check('「让她回来」能叫回来', !!r && r.shown === true, '');
    check('点完全部开关（来回各一次）没有未捕获异常', !!r && r.errCount === 0, r ? r.errText : '');
  }
});

// ── 前端专项：弹窗「检测 API 连接」的报错要能一眼定位 ────────────────────────
// 现场故障：用户 API 没钱（服务商 402 Insufficient Balance），旧实现显示
// 「连接失败 (402): {JSON}」—— 用户去查网络、重装插件，唯独没想到充值。
// 现在报错经 libs/api-error.js 分类：人看到「【账户余额不足】…去充值」。
// 注意这条场景**必须把 forcedStatus 还原**，否则后面所有答题场景一起挂。
SCENARIOS.push({
  name: '弹窗测试连接：没钱（402）显示「余额不足」而不是「连接失败」',
  url: 'chrome-extension://{EXT}/popup/popup.html?ui=fancy',
  inject: false,
  run: async function (ctx) {
    ctx.mock.setStatus(402);
    try {
      // 前提钉住"老键从没写过"这一族形状：批次 123-b 起表单不再发 thinkingLevel，于是
      // 「弹窗侧 DEFAULTS 兜成 off、后台侧读到空」的指纹错配只在全新档案才暴露 ——
      // 全量跑里只要前一场写过它，这条回归就变成零覆盖。先删干净，再把"真删了"读回来钉住。
      var legacyCleared = await ctx.client.evaluate(
        'new Promise(function (res) { chrome.storage.local.get("config", function (r) {' +
        'var c = r.config || {}; delete c.thinkingLevel; delete c.thinkingPaperLevel;' +
        'chrome.storage.local.set({ config: c }, function () {' +
        'res({ level: Object.prototype.hasOwnProperty.call(c, "thinkingLevel"), ' +
        'paper: Object.prototype.hasOwnProperty.call(c, "thinkingPaperLevel") }); }); }); })'
      );
      check('前提：存储里两个思考老键都没写过（新用户那一族）',
        !!legacyCleared && legacyCleared.level === false && legacyCleared.paper === false,
        JSON.stringify(legacyCleared));
      // ⚠️ 「检测 API」读的是**表单**（getApiFormConfig），不是 storage ——
      // 表单也不随 storage.onChanged 刷新（那个监听只管运行状态）。
      // 所以必须直接填表单字段；写 storage 不仅没用，还会让请求打到真实服务商。
      await ctx.client.evaluate(
        '(function(){' +
        'document.getElementById("apiUrl").value = "http://127.0.0.1:' + PORT + '";' +
        'document.getElementById("apiKey").value = "sk-e2e-classification";' +
        'document.getElementById("model").value = "mock-model";' +
        'return true;})()'
      );
      await sleep(150);
      await ctx.client.evaluate('document.getElementById("testApi").click()');
      // 处理链：ping（≤1.5s）→ 请求 mock → patch 配置 → toast；轮询等 toast 落定
      var toast = '';
      for (var i = 0; i < 40; i++) {
        await sleep(150);
        toast = await ctx.client.evaluate('String(document.getElementById("toast").textContent || "")');
        if (/余额不足|连接失败/.test(toast)) break;
      }
      check('402 的 toast 说出「余额不足」并给出下一步（不再叫连接失败）',
        /余额不足/.test(toast) && /充值/.test(toast) && !/连接失败/.test(toast),
        toast.slice(0, 140));

      var stored = await ctx.client.evaluate(
        'new Promise(function (res) { chrome.storage.local.get("config", function (r) {' +
        'res({ failed: !!(r.config || {}).apiConnectionFailed,' +
        'err: String((r.config || {}).apiConnectionError || "") }); }); })'
      );
      check('写进配置的 apiConnectionError 也是分类后的人话（弹窗横幅同源）',
        /余额不足/.test(stored.err) && !/^\s*连接失败 \(\d+\)/.test(stored.err),
        JSON.stringify(stored).slice(0, 160));
      var shown = await ctx.client.evaluate(
        '(function(){var el=document.getElementById("apiConnState");' +
        'return {hidden:!!(el&&el.hidden),text:String((el||{}).textContent||"")};})()'
      );
      check('弹窗状态行常驻显示分类后的人话（storage.onChanged 同步）',
        !!shown && shown.hidden === false && /余额不足/.test(shown.text),
        JSON.stringify(shown));
    } finally {
      ctx.mock.setStatus(0);
    }
  }
});

// ── 前端专项：成长小游戏（好感度 / 等级 / 刷课时长）─────────────────────────
// 断言的是**行为**：摸头之后共享存档（chrome.storage 的 omitonePetBond）里好感真的涨了、
// 徽章真的换了字、刷课时长真的按水位折算 —— 不是查内部函数是否存在。
// ⚠️ 摸头三连（2 秒内 3 次）会触发"躲开"，不涨好感 —— 每次点击之间要拉开间隔。
// ⚠️ 存档真源是 chrome.storage（与上课页伴侣共享）：改完要等 onChanged 传回弹窗内存
//    再点（直接改完立刻点，摸的还是旧内存态）。
SCENARIOS.push({
  name: '小游戏：摸头涨好感、跨级换徽章、刷课时长折算',
  url: 'chrome-extension://{EXT}/popup/popup.html?play=1&ui=fancy',
  inject: false,
  run: async function (ctx) {
    var ui = await ctx.client.evaluate(
      '(function(){return {game:!!self.OmitonePetGame,' +
      'bond:!!document.getElementById("petBond"),badge:!!document.getElementById("petLevel")};})()'
    );
    check('前提：pet-game 已加载，好感条与等级徽章都在',
      !!ui && ui.game === true && ui.bond === true && ui.badge === true, JSON.stringify(ui));

    // 从零开始：把共享存档**拨零**（必须用 set 不能用 remove ——
    // remove 的 changes.newValue 为空、弹窗内存里的旧档会存活下来，
    // 后续摸头全从旧值续；set 会触发 onChanged 把内存一起归零。实测踩过）
    await ctx.client.evaluate(
      'new Promise(function (res) {' +
      'try { localStorage.removeItem("omitone.pet.bond"); } catch (e) {}' +
      'var game = self.OmitonePetGame;' +
      'var fresh = {affection: 0, day: game.dayKeyOf(Date.now()), patsToday: 0, studyPointsToday: 0, countedSeconds: 0};' +
      'chrome.storage.local.set({ omitonePetBond: fresh }, function () { res(true); }); })'
    );
    await sleep(400);   // onChanged → 弹窗内存归零

    // 摸头一下 → 好感 +1 入共享存档
    await ctx.client.evaluate('document.getElementById("mascot").click()');
    await sleep(300);
    var afterPat = await ctx.client.evaluate(
      'new Promise(function (res) { chrome.storage.local.get("omitonePetBond", function (r) {' +
      'res(r && r.omitonePetBond ? r.omitonePetBond : null); }); })'
    );
    check('摸头一次 → 好感 +1 入共享存档', !!afterPat && afterPat.affection === 1, JSON.stringify(afterPat));

    // 刷课时长折算：写 1 小时统计、清零水位 → 等 onChanged 传回 → 摸头触发结算 → +2
    await ctx.client.evaluate(
      'new Promise(function (res) {' +
      'var game = self.OmitonePetGame;' +
      'var st = {date: game.dayKeyOf(Date.now()), activeSeconds: 3600, lastActiveAt: Date.now(), lastFlushAt: Date.now()};' +
      'chrome.storage.local.set({ omitoneStudyStats: st }, function () {' +
      'chrome.storage.local.get("omitonePetBond", function (r) {' +
      'var bond = r.omitonePetBond; bond.countedSeconds = 0;' +
      'chrome.storage.local.set({ omitonePetBond: bond }, function () { res(true); }); }); }); })'
    );
    await sleep(400);   // onChanged → 弹窗内存
    await sleep(2200);  // 与上一次摸头拉开 2 秒，避免触发"三连戳躲开"
    await ctx.client.evaluate('document.getElementById("mascot").click()');
    await sleep(300);
    var afterStudy = await ctx.client.evaluate(
      'new Promise(function (res) { chrome.storage.local.get("omitonePetBond", function (r) {' +
      'res(r && r.omitonePetBond ? r.omitonePetBond : null); }); })'
    );
    check('1 小时刷课折 6 点好感（10 分钟 1 点；触发结算的那次摸头本身也 +1 → 1+1+6=8；水位停在 3600 秒）',
      !!afterStudy && afterStudy.affection === 8 && afterStudy.countedSeconds === 3600 && afterStudy.patsToday === 2,
      JSON.stringify(afterStudy));

    // 跨级：把好感拨到 14 → 等 onChanged → 再摸一下 → 15 → 徽章换「打过招呼」
    await ctx.client.evaluate(
      'new Promise(function (res) { chrome.storage.local.get("omitonePetBond", function (r) {' +
      'var bond = r.omitonePetBond; bond.affection = 14; bond.patsToday = 0;' +
      'chrome.storage.local.set({ omitonePetBond: bond }, function () { res(true); }); }); })'
    );
    await sleep(400);
    // 拨 14 → 等 onChanged 传回弹窗内存 → 摸头 → 跨级。时序经过实测：
    // set 之后 400ms 点击（探针验证过的路径）；更长的等待反而会撞上闲置演出，不划算
    var leveled = await ctx.client.evaluate(
      'new Promise(function (res) {' +
      'var errs = [];' +
      'window.addEventListener("error", function (e) { errs.push(String(e.message || e)); });' +
      'function readBond(done) {' +
      '  chrome.storage.local.get("omitonePetBond", function (r) { done(r && r.omitonePetBond || null); });' +
      '}' +
      'readBond(function (bond) {' +
      '  bond.affection = 14; bond.patsToday = 0;' +
      '  chrome.storage.local.set({ omitonePetBond: bond }, function () {' +
      '    setTimeout(function () {' +
      '      document.getElementById("mascot").click();' +
      '      setTimeout(function () {' +
      '        readBond(function (bond2) {' +
      '          res({badge: String(document.getElementById("petLevel").textContent || ""),' +
      '              aff: bond2 ? bond2.affection : null,' +
      '              errs: errs});' +
      '        });' +
      '      }, 400);' +
      '    });' +
      '  });' +
      '});' +
      '});'
    );
    check('好感到 15 → 徽章换成「打过招呼」（无页面异常）',
      !!leveled && leveled.badge === '打过招呼' && leveled.aff === 15 && leveled.errs.length === 0,
      JSON.stringify(leveled));

    // ⑦ 升级那一句的**归因**（批次 65：这一句以前是弹窗里拼出来的，现在只从规则层 levelup 那一族出）。
    //    ⚠️ 断言不钉句子字面（钉字面=把台词池抄第二份），钉的是三件可读回来的事：
    //      登记成哪一族、气泡与归因格同一句、**徽章那一档的名字真的进了句子**（名字从页面 DOM 读回来，
    //      不是测试里的常量）—— 拼接漏了字段、忘写归因、填了个 undefined，这三种都会红。
    var saidLevel = await ctx.client.evaluate(
      '(function(){var m=document.getElementById("mascot");' +
      'var b=document.getElementById("mascotBubble");' +
      'var d=(m&&m.dataset)?m.dataset:{};' +
      'return {from:String(d.sayFrom||""),attr:String(d.sayLine||""),' +
      'bubble:String(b?b.textContent:""),badge:String(document.getElementById("petLevel").textContent||"")};})()'
    );
    check('跨级那一句登记成 levelup 这一族，气泡与归因格同一句',
      !!saidLevel && saidLevel.from === 'levelup' && saidLevel.attr.length > 0 &&
      saidLevel.attr === saidLevel.bubble, JSON.stringify(saidLevel));
    check('升级那句真的把新等级名填进去了（徽章那一档出现在句子里，且没留占位/undefined）',
      !!saidLevel && saidLevel.badge.length > 0 && saidLevel.attr.indexOf(saidLevel.badge) >= 0 &&
      !/\{/.test(saidLevel.attr) && !/undefined/.test(saidLevel.attr), JSON.stringify(saidLevel));

    // ⑧ 日报那一句（「今天已经一起刷了 N 分钟」）：只在**弹窗初始化**那一次说，所以要重载才测得到。
    //    ⚠️ 跨 reload 的轮询必须等 `readyState==="complete"`，不是等 `getElementById` 拿到元素 ——
    //      元素先有、监听器后挂，正好落在这个缝里读数会得到一条**看着像台词写错了**的红。
    //    ⚠️ 每一趟自己把依赖的共享状态钉住（统计=今天 3600 秒、水位=3600 让结算空转、好感按档位拨）：
    //      不钉的话，前一个场景写过的 stats 会让"这一趟压根不在要求的那一档里"和"她没说"同形。
    //    水位钉成与 activeSeconds 相等 → `applyStudySeconds` 折出 0 点 → 初始化那一下不会顺手升级，
    //    否则 levelup 那一族会把归因格盖掉，日报这一族变成零覆盖。
    var dailyProbe = async function (affection) {
      await ctx.client.evaluate(
        'new Promise(function (res) {' +
        'var game = self.OmitonePetGame; var k = game.dayKeyOf(Date.now());' +
        'var st = { date: k, activeSeconds: 3600, lastActiveAt: Date.now(), lastFlushAt: Date.now() };' +
        'chrome.storage.local.set({ omitoneStudyStats: st }, function () {' +
        '  chrome.storage.local.get("omitonePetBond", function (r) {' +
        '    var b = (r && r.omitonePetBond) || { day: k };' +
        '    b.affection = ' + affection + '; b.day = k; b.countedSeconds = 3600;' +
        '    b.patsToday = 0; b.studyPointsToday = 0; b.ach = b.ach || {};' +
        '    chrome.storage.local.set({ omitonePetBond: b }, function () { res(true); });' +
        '  });' +
        '}); })'
      );
      await sleep(250);   // onChanged 把内存拨过去，免得 reload 后第一拍又拿旧档写回存档
      // 钉住深夜那一格：23:00–05:00 打开小窗她会补一句「nightWarn」，把日报顶掉。
      // 全量跑什么时候都可能落在夜里，不钉的话这条断言就成了"看钟点"的随机红。
      await ctx.client.evaluate('(function(){localStorage.setItem("omitone.pet.night", String(Date.now()));return true;})()');
      await ctx.client.send('Page.reload', { ignoreCache: false });
      var done = false;
      for (var rw = 0; rw < 40; rw++) {
        await sleep(120);
        done = await ctx.client.evaluate(
          '(function(){return document.readyState==="complete"&&!!document.getElementById("mascot");})()'
        );
        if (done) break;
      }
      await sleep(700);   // 初始化里那次 chrome.storage.local.get 的回调 + 台词落气泡
      return await ctx.client.evaluate(
        '(function(){var m=document.getElementById("mascot");' +
        'var b=document.getElementById("mascotBubble");' +
        'return {ready:document.readyState,hidden:document.hidden,' +
        'shown:m?String(m.style.display||""):"无",from:m?String(m.dataset.sayFrom||""):"",' +
        'attr:m?String(m.dataset.sayLine||""):"",bubble:b?String(b.textContent||""):""};})()'
      );
    };
    var dailyLow = await dailyProbe(15);
    var dailyHigh = await dailyProbe(40);
    var minsBack = await ctx.client.evaluate(
      'new Promise(function (res) { chrome.storage.local.get("omitoneStudyStats", function (r) {' +
      'var st = r && r.omitoneStudyStats;' +
      'res(st ? { date: String(st.date || ""), mins: Math.floor((Number(st.activeSeconds) || 0) / 60) } : null); }); })'
    );
    check('前提：日报这两趟都真的走在要求的那一档里（重载完成、她可见、统计是今天且够 5 分钟）',
      !!dailyLow && dailyLow.ready === 'complete' && dailyLow.hidden === false &&
      dailyLow.shown !== 'none' && dailyHigh && dailyHigh.hidden === false &&
      !!minsBack && minsBack.date.length > 0 && minsBack.mins >= 5,
      JSON.stringify({ low: dailyLow, high: dailyHigh, mins: minsBack }));
    check('日报按好感度分档：15 走 daily、到 30 以上走 dailyHigh（两句都登记得回来、气泡同源）',
      !!dailyLow && dailyLow.from === 'daily' && dailyLow.attr === dailyLow.bubble &&
      dailyLow.attr.length > 0 && !!dailyHigh && dailyHigh.from === 'dailyHigh' &&
      dailyHigh.attr === dailyHigh.bubble && dailyHigh.attr.length > 0,
      JSON.stringify({ low: dailyLow, high: dailyHigh }));
    check('日报那句里的分钟数是从存储读回来的那个数，且没留占位/undefined',
      !!dailyLow && !!minsBack && dailyLow.attr.indexOf(String(minsBack.mins)) >= 0 &&
      !/\{/.test(dailyLow.attr) && !/undefined/.test(dailyLow.attr) &&
      !/\{/.test(dailyHigh.attr) && !/undefined/.test(dailyHigh.attr),
      JSON.stringify({ low: dailyLow.attr, high: dailyHigh.attr, mins: minsBack }));

    // ── 记忆翻牌（批次 108）：点「玩」开面板、照 data-face 打出完美一局、首胜 +1 ──
    // ⚠️ 成就格先全部预点亮：配对胜利本身不碰任何成就 need，但好感/streak 的常规变动
    //    可能顺手点亮别的成就 —— 成就台词会顶掉 gamewin 那一句，归因断言就红了。
    var gameSetup = await ctx.client.evaluate(
      'new Promise(function (res) {' +
      'var game = self.OmitonePetGame; var k = game.dayKeyOf(Date.now());' +
      'chrome.storage.local.get("omitonePetBond", function (r) {' +
      'var b = (r && r.omitonePetBond) || { day: k };' +
      'b.day = k; b.patsToday = 0; b.studyPointsToday = 0; b.countedSeconds = 3600;' +
      'b.ach = {}; (game.ACHIEVEMENTS || []).forEach(function (a) { b.ach[a.id] = k; });' +
      'b.memoryRewardDay = "";' +
      'chrome.storage.local.set({ omitonePetBond: b }, function () { res({ aff: b.affection }); }); }); })'
    );
    await sleep(400);   // onChanged → 弹窗内存
    await ctx.client.evaluate('document.querySelector(\'.pet-tools button[data-act="game"]\').click()');
    await sleep(250);
    var gamePanel = await ctx.client.evaluate(
      '(function(){var p=document.getElementById("petGame");' +
      'var cards=[].slice.call(document.querySelectorAll("#petGameBody .pet-card"));' +
      'var faces={};cards.forEach(function(c){faces[c.getAttribute("data-face")]=1;});' +
      'return {shown:p.classList.contains("show"),aria:p.getAttribute("aria-hidden"),' +
      'cards:cards.length,faces:Object.keys(faces).length};})()'
    );
    check('点「玩」→ 记忆翻牌面板亮起，12 张卡 = 6 对表情',
      !!gamePanel && gamePanel.shown === true && gamePanel.aria === 'false' &&
      gamePanel.cards === 12 && gamePanel.faces === 6, JSON.stringify(gamePanel));
    // 完美一局：按 data-face 两两配对点完。配对分支是同步记账（done 立刻落），
    // 中途无错配就全程无 busy 锁 —— 12 发连点安全；最后那一对 320ms 后触发结算。
    var winRound = async function () {
      await ctx.client.evaluate(
        '(function(){var cards=[].slice.call(document.querySelectorAll("#petGameBody .pet-card"));' +
        'var by={};cards.forEach(function(c){var f=c.getAttribute("data-face");(by[f]=by[f]||[]).push(c);});' +
        'Object.keys(by).forEach(function(f){by[f][0].click();by[f][1].click();});' +
        'return cards.length;})()'
      );
      await sleep(700);   // 320ms 结算回调 + persistBond 落盘
      return await ctx.client.evaluate(
        'new Promise(function (res) { chrome.storage.local.get("omitonePetBond", function (r) {' +
        'var b = r && r.omitonePetBond;' +
        'var m = document.getElementById("mascot");' +
        'res({bond: b, from: m ? String(m.dataset.sayFrom || "") : ""}); }); })'
      );
    };
    var r1 = await winRound();
    check('首胜入账：好感 +1、memoryRewardDay 记今天、最佳 6 步、胜场 1，台词登记成 gamewin',
      !!r1 && !!r1.bond && r1.bond.affection === Number(gameSetup.aff) + 1 &&
      r1.bond.memoryRewardDay === r1.bond.day && r1.bond.memoryBestMoves === 6 &&
      r1.bond.memoryWins === 1 && r1.from === 'gamewin',
      JSON.stringify({ aff0: gameSetup.aff, bond: r1 && r1.bond, from: r1 && r1.from }));
    // 工具条按钮是开关：开着时点一下是**收起**。第二局要关一次、再开一次
    //（openGame 才会重置棋盘重发牌），只点一下第二局的点击全会被关着的面板拒掉。
    await ctx.client.evaluate('document.querySelector(\'.pet-tools button[data-act="game"]\').click()');
    await sleep(250);
    await ctx.client.evaluate('document.querySelector(\'.pet-tools button[data-act="game"]\').click()');
    await sleep(250);
    var r2 = await winRound();
    check('同天第二局纯玩：好感不再涨、胜场照记、领奖日不变',
      !!r2 && !!r2.bond && r2.bond.affection === Number(gameSetup.aff) + 1 &&
      r2.bond.memoryWins === 2 && r2.bond.memoryRewardDay === r1.bond.memoryRewardDay,
      JSON.stringify(r2 && r2.bond));
    var escClosed = await ctx.client.evaluate(
      '(function(){document.dispatchEvent(new KeyboardEvent("keydown",{key:"Escape"}));' +
      'var p=document.getElementById("petGame");' +
      'return {shown:p.classList.contains("show"),aria:p.getAttribute("aria-hidden")};})()'
    );
    check('Esc 关得上面板（aria-hidden 同步回 true）',
      !!escClosed && escClosed.shown === false && escClosed.aria === 'true', JSON.stringify(escClosed));
  }
});

// ── 前端专项：上课页角色伴侣 ────────────────────────────────────────────────
// 弹窗合上角色就没了 —— 现在她跟到学习页（Shadow DOM 注入）。
// 主世界读不到 chrome.storage，所以断言全落在 Shadow DOM 的 UI 表现上：
// 立绘真的加载了（web_accessible 生效）、摸头后好感条真的动了、收起/唤回真的切状态。
// ── 批次 162：徽章那四个字一个都不许掉 ──────────────────────────────────────
// 用户 2026-11-21 现场：「我这里是"心有......"就没了，一共两个字」。
// 全仓**只有一处** CSS 会生成省略号：content.js 的 `.level{…text-overflow:ellipsis}`；
// 它原先挂在写死 `width:158px` 的 `.wrap` 里 → 可用宽度一旦小于文字宽度就把档名剪成"两字 + …"。
// 现场那台复现不出来（技能探针 `expr/pet-geom.expr` 读回：10px 字号、4 字徽章盒宽 54、槽位 75.67），
// 所以**成因不写死**：
// 任何把字变宽的环境（浏览器「最小字号」顶大那 10px 是最像的一族）都该被同一条尺挡住 ——
// 判据落在行为上：卡片随内容让位，徽章在任何字号下都不掉字、也不越过卡片右缘。
// ⚠️ 档名从真源 popup/pet-game.js 读回来，本文件不抄第二份（§5「断言里出现的每一个数，
//   都要说得出它是从哪读回来的」）；5136 行那份硬编码 LEVELS 副本是**另一把尺**，
//   改真源不会同步它 —— 本轮只保证不再新增副本，动那份要单独一轮对账。
var PET_LEVEL_NAMES = (function () {
  var src = String(fs.readFileSync(path.join(ROOT, 'popup/pet-game.js'), 'utf8'));
  var from = src.indexOf('var LEVELS = [');
  var to = from < 0 ? -1 : src.indexOf('];', from);
  var seg = from < 0 || to < 0 ? '' : src.slice(from, to);
  var out = [], re = /min:\s*(\d+)\s*,\s*name:\s*'([^']+)'/g, m;
  while ((m = re.exec(seg))) out.push(m[2]);
  return out;
})();

SCENARIOS.push({
  name: '上课页角色伴侣：等级徽章在任何字号下都不掉字（卡片随内容让位）',
  path: '/quiz',
  pagePetOn: true,
  noAutoResume: true,
  run: async function (ctx) {
    var longest = 0;
    PET_LEVEL_NAMES.forEach(function (n) { if (n.length > longest) longest = n.length; });
    // 前提自证：真源那份表要读得到，否则下面 30 格是零覆盖而不是"通过"（§5「红 0 条先怀疑没跑到」）
    check('前提：等级档名从真源 popup/pet-game.js 读回来 ' + PET_LEVEL_NAMES.length +
      ' 档、最长 ' + longest + ' 字（读空了这一场根本什么都没测）',
      PET_LEVEL_NAMES.length >= 8 && longest >= 4 &&
      PET_LEVEL_NAMES.every(function (n) { return n.length > 0 && n.length <= 4; }),
      JSON.stringify(PET_LEVEL_NAMES));

    var mounted = null;
    for (var i = 0; i < 24; i++) {
      await sleep(250);
      mounted = await ctx.client.evaluate(
        '(function(){var h=document.getElementById("omitone-page-pet-host");' +
        'if(!h||!h.shadowRoot)return null;' +
        'var lv=h.shadowRoot.getElementById("level");' +
        'return {lv:!!lv,text:String(lv.textContent||"")};})()');
      if (mounted && mounted.lv) break;
    }
    check('前提：徽章那一格真在 Shadow DOM 里（挂载失败时"没掉字"会变成一句假绿）',
      !!mounted && mounted.lv === true && mounted.text.length > 0, JSON.stringify(mounted));

    var cellCount = PET_LEVEL_NAMES.length * 3;
    var cells = await ctx.client.evaluate(
      '(function(){var h=document.getElementById("omitone-page-pet-host");var sr=h.shadowRoot;' +
      'var lv=sr.getElementById("level"),wrap=sr.getElementById("wrap"),card=sr.getElementById("card");' +
      'var names=' + JSON.stringify(PET_LEVEL_NAMES) + ';var fonts=[10,24,32];' +
      'var savedText=String(lv.textContent||""),savedStyle=lv.getAttribute("style")||"";' +
      // 每格读**两把独立的尺**：scrollWidth 对 clientWidth（省略号那把），
      // 以及 Range 量到的文字实宽 + 计算样式读回来的左右内边距 对 盒子宽（"字真的整个在药丸里"）。
      'function measure(){var cs=getComputedStyle(lv);' +
      'var pl=Number(parseFloat(cs.paddingLeft))||0,pr=Number(parseFloat(cs.paddingRight))||0;' +
      'var rg=document.createRange();rg.selectNodeContents(lv);var rr=rg.getBoundingClientRect();' +
      'if(rg.detach){rg.detach();}' +
      'var lr=lv.getBoundingClientRect(),cr=card.getBoundingClientRect();' +
      'return {sw:Math.ceil(lv.scrollWidth),cw:Math.floor(lv.clientWidth),pl:pl,pr:pr,' +
      'txt:Math.ceil(rr.width),box:Math.round(lr.width),spill:Math.round(lr.right-cr.right),' +
      'wrap:Math.round(wrap.getBoundingClientRect().width)};}' +
      'var base=measure(),out=[];' +
      'for(var f=0;f<fonts.length;f++){for(var n=0;n<names.length;n++){' +
      'lv.style.fontSize=fonts[f]+"px";lv.textContent=names[n];' +
      'var m=measure();m.font=fonts[f];m.name=names[n];out.push(m);}}' +
      // 收尾把页面交回来：这一格是渲染出来的，留着注入样式会毒化后面的场景（§5 共享状态）
      'if(savedStyle){lv.setAttribute("style",savedStyle);}else{lv.removeAttribute("style");}' +
      'lv.textContent=savedText;' +
      'return {base:base,cells:out,to:String(getComputedStyle(lv).textOverflow||""),restored:String(lv.textContent||"")};})()');

    var restored = await ctx.client.evaluate(
      '(function(){var h=document.getElementById("omitone-page-pet-host");' +
      'var lv=h.shadowRoot.getElementById("level");' +
      'return {style:lv.getAttribute("style")||"",text:String(lv.textContent||""),' +
      'fs:String(getComputedStyle(lv).fontSize)};})()');

    var bad = [];
    (cells && cells.cells || []).forEach(function (m) {
      if (m.sw > m.cw + 1) bad.push({ why: 'scrollWidth 溢出（省略号那一族）', name: m.name, font: m.font, sw: m.sw, cw: m.cw });
      else if (m.txt + m.pl + m.pr > m.box + 1) bad.push({ why: '文字比药丸还宽', name: m.name, font: m.font, txt: m.txt, box: m.box, pl: m.pl, pr: m.pr });
      if (m.spill > 1) bad.push({ why: '徽章越过卡片右缘', name: m.name, font: m.font, spill: m.spill });
    });
    var w10 = (cells && cells.cells || []).filter(function (m) { return m.font === 10; });
    var w32 = (cells && cells.cells || []).filter(function (m) { return m.font === 32; });
    var minW32 = 1e9;
    w32.forEach(function (m) { if (m.wrap < minW32) minW32 = m.wrap; });
    var maxW10 = -1;
    w10.forEach(function (m) { if (m.wrap > maxW10) maxW10 = m.wrap; });

    check('每一档 × 每一字号共 ' + cellCount + ' 格：徽章都不掉字（scrollWidth 与 Range 两把尺各测一遍），也不越过卡片右缘',
      !!cells && cells.cells.length === cellCount && cells.to === 'ellipsis' && bad.length === 0,
      JSON.stringify({ cells: cells ? cells.cells.length : -1, textOverflow: cells && cells.to, bad: bad.slice(0, 4) }));
    // 这一格是"机制真的在起作用"的对照：卡片没让位时下面两条**同时**成立才算修好 ——
    // 大字号下宽度必须**大于**默认宽度（让位了），默认字号下又必须**等于**默认宽度（观感没变）。
    check('卡片确实让出了位置，而不是恰好没超：32 像素字号下每一格都比默认宽度更宽；' +
      '而默认 10 像素下最长那档也不把卡片撑大（今天观感不变）· 读回卡片宽 ' +
      (cells && cells.base ? cells.base.wrap : -1) + '，大字号最窄 ' + minW32 +
      '，默认字号最宽 ' + maxW10,
      !!cells && cells.base.wrap > 100 && minW32 > cells.base.wrap && maxW10 === cells.base.wrap,
      JSON.stringify({ base: cells && cells.base, minW32: minW32, maxW10: maxW10 }));
    check('收尾把徽章交回原样（探针注入的字号与档名不许留给后面的场景）',
      !!cells && !!restored && restored.style === '' && restored.text === cells.restored,
      JSON.stringify({ probe: cells && cells.restored, now: restored }));
  }
});

SCENARIOS.push({
  name: '上课页角色伴侣：出现在学习页、摸头涨好感、收起与唤回',
  path: '/quiz',
  run: async function (ctx) {
    var mounted = null;
    for (var i = 0; i < 24; i++) {
      await sleep(250);
      mounted = await ctx.client.evaluate(
        '(function(){var h=document.getElementById("omitone-page-pet-host");' +
        'if(!h||!h.shadowRoot)return null;' +
        'var img=h.shadowRoot.getElementById("petImg");' +
        'var lv=h.shadowRoot.getElementById("level");' +
        'return {img:!!img,loaded:!!img&&img.naturalWidth>0,' +
        'level:String(lv.textContent||""),title:String(lv.getAttribute("title")||"")};})()'
      );
      if (mounted && mounted.img) break;
    }
    check('伴侣出现在学习页，且立绘真的加载了（web_accessible_resources 生效）',
      !!mounted && mounted.img === true && mounted.loaded === true, JSON.stringify(mounted));
    // 徽章那条旧断言是 `level.length > 0` —— 而模板里 `<div class="level" id="level">初识</div>`
    // 出厂就带字（content.js:1895），渲染整段坏掉它照样绿。真判据是**渲染出来的那一档**：
    // `title` 只有 `renderPagePet` 跑过才会有（content.js:1701），
    // 再从里面读回好感度，按 LEVELS 阈值算出该显示哪一档名字。
    // 存档是异步读的，元素先出现、渲染后落，所以这里要再等一拍（最多 3 秒），不能拿首次采样当结论。
    for (var tw = 0; tw < 12; tw++) {
      if (mounted && /^好感度/.test(mounted.title)) break;
      await sleep(250);
      mounted = await ctx.client.evaluate(
        '(function(){var h=document.getElementById("omitone-page-pet-host");' +
        'if(!h||!h.shadowRoot)return null;' +
        'var lv=h.shadowRoot.getElementById("level");' +
        'return {level:String(lv.textContent||""),title:String(lv.getAttribute("title")||"")};})()'
      );
    }
    var lvMin = [0, 15, 30, 50, 70, 90, 140, 200];
    var lvName = ['初识', '打过招呼', '熟络', '亲近', '挚友', '形影不离', '心有灵犀', '岁月同行'];
    var affMatch = /好感度\s*(\d+)/.exec((mounted && mounted.title) || '');
    var aff = affMatch ? Number(affMatch[1]) : -1;
    var expectName = null;
    for (var li = lvMin.length - 1; li >= 0; li--) { if (aff >= lvMin[li]) { expectName = lvName[li]; break; } }
    check('等级徽章按存档渲染（不是模板里那句出厂文案）：' +
      'title 里的「好感度 ' + aff + '」对应「' + expectName + '」',
      !!mounted && aff >= 0 && expectName === mounted.level, JSON.stringify(mounted));

    // 摸头：好感条宽度发生变化（存档在 storage，主世界读不到 —— 断 UI 表现）
    var before = await ctx.client.evaluate(
      '(function(){var h=document.getElementById("omitone-page-pet-host");' +
      'return h.shadowRoot.getElementById("bondBar").style.width||"";})()'
    );
    await ctx.client.evaluate(
      '(function(){var h=document.getElementById("omitone-page-pet-host");' +
      'h.shadowRoot.getElementById("petImg").click();return true;})()'
    );
    await sleep(350);
    var after = await ctx.client.evaluate(
      '(function(){var h=document.getElementById("omitone-page-pet-host");' +
      'return {w:h.shadowRoot.getElementById("bondBar").style.width||"",' +
      'bubbleCls:String(h.shadowRoot.getElementById("bubble").className||"")};})()'
    );
    check('摸头后好感条动了、气泡给了反馈',
      !!after && after.w !== before && /show/.test(after.bubbleCls),
      JSON.stringify({ before: before, after: after }));

    // 收起 → 只剩小入口；点入口 → 唤回
    await ctx.client.evaluate(
      '(function(){var h=document.getElementById("omitone-page-pet-host");' +
      'h.shadowRoot.getElementById("hideBtn").click();return true;})()'
    );
    await sleep(250);
    var hidden = await ctx.client.evaluate(
      '(function(){var h=document.getElementById("omitone-page-pet-host");' +
      'return String(h.shadowRoot.getElementById("wrap").className||"");})()'
    );
    check('「收」后进入隐藏模式（角色藏起、留小入口）', /mode-hidden/.test(hidden), hidden);
    await ctx.client.evaluate(
      '(function(){var h=document.getElementById("omitone-page-pet-host");' +
      'h.shadowRoot.getElementById("pillBtn").click();return true;})()'
    );
    await sleep(250);
    var restored = await ctx.client.evaluate(
      '(function(){var h=document.getElementById("omitone-page-pet-host");' +
      'return String(h.shadowRoot.getElementById("wrap").className||"");})()'
    );
    check('点「宠」唤回（隐藏模式解除）', !/mode-hidden/.test(restored), restored);

    // ── 2026-11-12 现场补的三条 ────────────────────────────────────────────
    // 上面那四条（挂载/摸头/收起/唤回）在拖动整个坏掉的那几天**全是绿的** ——
    // 因为它们一条都没碰"她往哪儿摆、说话是什么形状、拖得动吗"。用户看到的正是这三样。
    // ① 气泡形状：旧 CSS 是 `left:66px` 挂在 92px 宽的 wrap 里，可用宽度只剩 26px，
    //    `max-width:200px` 只是上限不会把盒子撑开 → 每行一个字，现场量到 31×215 的竖排。
    var bubbleShape = await ctx.client.evaluate(
      '(function(){var h=document.getElementById("omitone-page-pet-host");' +
      'var b=h.shadowRoot.getElementById("bubble");' +
      'b.textContent="\u6210\u5c31\u70b9\u4eae\u300c\u4e09\u65e5\u6253\u9c7c\u300d\u2014\u2014 \u8fd9\u4e00\u5468\u4f60\u90fd\u5728\u8ba4\u771f\u5237\u8bfe\uff0c\u597d\u611f\u5ea6\u53c8\u8fd1\u4e86\u4e00\u6b65\uff1b\u518d\u591a\u6765\u51e0\u5929\u5c31\u80fd\u5347\u5230\u300c\u8001\u670b\u53cb\u300d\u3002";' +
      'b.classList.add("show");var r=b.getBoundingClientRect();' +
      'return {w:Math.round(r.width),h:Math.round(r.height),left:Math.round(r.left),right:Math.round(r.right),vw:window.innerWidth};})()'
    );
    check('气泡是横排的一小块，不再每行一个字（旧形状 31×215）',
      !!bubbleShape && bubbleShape.w >= 120 && bubbleShape.h <= 110 &&
      bubbleShape.w >= bubbleShape.h * 1.2 && bubbleShape.left >= 0 && bubbleShape.right <= bubbleShape.vw,
      JSON.stringify(bubbleShape));
    await ctx.client.evaluate(
      '(function(){var h=document.getElementById("omitone-page-pet-host");' +
      'var b=h.shadowRoot.getElementById("bubble");b.textContent="";b.classList.remove("show");return true;})()'
    );

    // ② 拖动：pointerdown 要挂上 dragging、move 之后 host 真的跟着走。
    //    ⚠️ 这条是本轮真正的回归闸：拖动 handler 里曾引用了块级作用域外的裸 `host`
    //    （`const host` 只在构建那个 try 块里存在），ReferenceError 被 handler 自己的
    //    catch 吞掉 → 现场表现为"拖不动、日志一条没有"，而沙盒四条全绿。
    //    收尾用 pointercancel —— 批次 178 起它**会**把落点写进存档（见下面 ⑨ 那六格），
    //    所以这里只把 inline 位置清回默认锚点，存档那一格留给 ⑨ 之后统一收干净。
    var drag = await ctx.client.evaluate(
      '(function(){var h=document.getElementById("omitone-page-pet-host");' +
      'var c=h.shadowRoot.getElementById("card");var errs=[];' +
      'window.addEventListener("error",function(e){errs.push(String(e.message||e));});' +
      'var r0=h.getBoundingClientRect();var x=r0.left+20,y=r0.top+20;' +
      'function pe(t,px,py){c.dispatchEvent(new PointerEvent(t,{bubbles:true,cancelable:true,composed:true,' +
      'pointerId:3,pointerType:"mouse",isPrimary:true,button:0,buttons:(t==="pointercancel"||t==="pointerup")?0:1,clientX:px,clientY:py}));}' +
      // 往左上拖：这个方向在沙盒视口里不会撞边界，位移必须**逐像素等于**手指位移
      'pe("pointerdown",x,y);var clsDown=String(c.className);' +
      'pe("pointermove",x-120,y+90);var r1=h.getBoundingClientRect();' +
      'pe("pointercancel",x-120,y+90);var clsEnd=String(c.className);' +
      // 再往右外拖：越界必须被 clamp 拉回屏内（留 8px 边），不许拖出窗口再也点不到
      'var r2=h.getBoundingClientRect();var ax=r2.left+20,ay=r2.top+20;' +
      'pe("pointerdown",ax,ay);pe("pointermove",ax+900,ay);var r3=h.getBoundingClientRect();' +
      'pe("pointercancel",ax+900,ay);' +
      'var w=Math.round(r3.width);' +
      'h.style.left="";h.style.top="";h.style.right="84px";h.style.bottom="176px";' +
      'return {clsDown:clsDown,clsEnd:clsEnd,dx:Math.round(r1.left-r0.left),dy:Math.round(r1.top-r0.top),' +
      'clampedLeft:Math.round(r3.left),clampExpect:Math.round(window.innerWidth)-w-8,errs:errs};})()'
    );
    check('拖得动：按住挂 dragging、位移逐像素跟着手指、松手类清掉、拖出右缘被 clamp 回屏内',
      !!drag && /dragging/.test(drag.clsDown) && !/dragging/.test(drag.clsEnd) &&
      drag.dx === -120 && drag.dy === 90 && drag.clampedLeft === drag.clampExpect && drag.errs.length === 0,
      JSON.stringify(drag).slice(0, 220));

    // ③ 她不再压在右下角那两块东西上。沙盒里状态面板**不会出现**（批次 146 起页面里那张
    //    「开始」卡片已删，状态面板只由弹窗「开始运行」那条启动链路挂上；吉祥物则随页面加载挂载），
    //    所以这里断的是现场量出来的两条"让位带"，而不是去比一个不存在的矩形：
    //      · 状态面板 bottom:18 + 高约 120 → 视口底部 138px 是它的带子
    //      · 学习通自己的右侧竖条 .iconBox 宽 40、左边缘在 vw-70
    //    实测默认锚点 right:84 / bottom:176 → 右边缘留 84、底边留 176，两条都过。
    var geo = await ctx.client.evaluate(
      '(function(){var h=document.getElementById("omitone-page-pet-host");' +
      'var c=h.shadowRoot.getElementById("card");var b=c.getBoundingClientRect();' +
      'return {rightGap:Math.round(window.innerWidth-b.right),bottomGap:Math.round(window.innerHeight-b.bottom),' +
      'vw:window.innerWidth,vh:window.innerHeight,w:Math.round(b.width),h:Math.round(b.height),' +
      'l:Math.round(b.left),t:Math.round(b.top)};})()'
    );
    check('默认锚点让开右下角两块地：右侧 ≥70px（站点竖条）、底部 ≥140px（状态面板带）',
      !!geo && geo.rightGap >= 70 && geo.bottomGap >= 140 &&
      geo.l >= 0 && geo.t >= 0 && geo.l + geo.w <= geo.vw && geo.t + geo.h <= geo.vh,
      JSON.stringify(geo).slice(0, 220));

    // ④ 心形的落点。这一条以前**根本没有**，所以"把视口坐标当 wrap 内坐标"那个 bug
    //    （1699 宽的屏上把她扔到屏外一千多像素）改坏了也没人报警 —— 反向验证注入它，红 0 条。
    //    判据用**相对 wrap 原点**的期望值比：合成 click 的 clientX=0，
    //    处理器会退回"立绘中心"，所以期望值算得出来，且与随机抖动（±13/±5）留了余量。
    var hearts = await ctx.client.evaluate(
      '(function(){var h=document.getElementById("omitone-page-pet-host");' +
      'var sr=h.shadowRoot;var img=sr.getElementById("petImg");' +
      'Array.prototype.forEach.call(sr.querySelectorAll(".heart"),function(x){x.remove();});' +
      'img.click();' +
      'var list=Array.prototype.slice.call(sr.querySelectorAll(".heart"));' +
      'var wr=sr.getElementById("wrap").getBoundingClientRect();' +
      'var ir=img.getBoundingClientRect();' +
      'var got=list.map(function(x){return {l:Math.round(parseFloat(x.style.left)||0),t:Math.round(parseFloat(x.style.top)||0)};});' +
      'var wantL=Math.round(ir.left+ir.width/2-wr.left),wantT=Math.round(ir.top+8-wr.top);' +
      'var bad=got.filter(function(p){return Math.abs(p.l-wantL)>18||Math.abs(p.t-wantT)>18;});' +
      'return {n:got.length,wantL:wantL,wantT:wantT,bad:bad.length,sample:got.slice(0,2),offscreen:got.filter(function(p){return p.l>window.innerWidth||p.t>window.innerHeight;}).length};})()'
    );
    check('摸头的心形长在她身上：4 颗、按 wrap 原点定位、没有一颗被扔到视口外',
      !!hearts && hearts.n === 4 && hearts.bad === 0 && hearts.offscreen === 0,
      JSON.stringify(hearts).slice(0, 220));

    // ⑤ 悬停反应（用户原话"交互也基本上不会动"）。走 pointerenter 而不是 CSS :hover：
    //    Runtime.evaluate 派发不出真·悬停态，纯 CSS 写法等于没测试。
    var hover = await ctx.client.evaluate(
      '(function(){var h=document.getElementById("omitone-page-pet-host");' +
      'var c=h.shadowRoot.getElementById("card");var im=h.shadowRoot.getElementById("petImg");' +
      'function pe(t){im.dispatchEvent(new PointerEvent(t,{bubbles:false,cancelable:true,composed:true,' +
      'pointerId:7,pointerType:"mouse",clientX:0,clientY:0}));}' +
      'var base=getComputedStyle(c).boxShadow;' +
      'pe("pointerenter");var on=c.classList.contains("peek");' +
      'var shadowOn=getComputedStyle(c).boxShadow,borderOn=getComputedStyle(c).borderColor;' +
      'pe("pointerleave");var off=c.classList.contains("peek");' +
      'return {on:on,off:off,changed:shadowOn!==base,back:getComputedStyle(c).boxShadow===base,' +
      'borderOn:borderOn,base:base,on2:shadowOn};})()'
    );
    check('鼠标移上去她真的有反应（peek 挂上、阴影/边框换了色），移开就收回',
      !!hover && hover.on === true && hover.off === false && hover.changed === true && hover.back === true,
      JSON.stringify(hover).slice(0, 240));

    // ⑤b 批次 176 的两条落点：#230「卡片身体不许吃掉页面」与 #206「收成小入口后还拖得动」。
    //     真·悬停派发不出（见上），但 elementFromPoint 与合成指针事件都跑得动 —— 断言只认这两个读数。
    var passthru = await ctx.client.evaluate(
      '(function(){var h=document.getElementById("omitone-page-pet-host");var sr=h.shadowRoot;' +
      'var c=sr.getElementById("card"),img=sr.getElementById("petImg"),hide=sr.getElementById("hideBtn");' +
      'function hit(el){var r=el.getBoundingClientRect();var p=document.elementFromPoint(r.left+r.width/2,r.top+r.height/2);' +
      'return (p===h)||(!!(p&&p.id==="omitone-page-pet-host"));}' +
      'return {body:hit(c),bodyW:Math.round(c.getBoundingClientRect().width),img:hit(img),hide:hit(hide),' +
      'wrapPe:getComputedStyle(sr.getElementById("wrap")).pointerEvents};})()'
    );
    check('卡片身体不再吃掉页面（中间点穿透回页面，立绘与「收」按钮仍然归她）',
      !!passthru && passthru.bodyW > 120 && passthru.body === false
      && passthru.img === true && passthru.hide === true && passthru.wrapPe === 'none',
      JSON.stringify(passthru).slice(0, 220));

    var dragPill = await ctx.client.evaluate(
      '(function(){var h=document.getElementById("omitone-page-pet-host");var sr=h.shadowRoot;' +
      'var w=sr.getElementById("wrap"),c=sr.getElementById("card"),pill=sr.getElementById("pillBtn");' +
      'w.classList.add("mode-hidden");' +
      'var rp=pill.getBoundingClientRect();' +
      'var wrapW=Math.round(w.getBoundingClientRect().width),pillW=Math.round(rp.width);' +
      'var x=rp.left+rp.width/2,y=rp.top+rp.height/2;' +
      'function pe(t){pill.dispatchEvent(new PointerEvent(t,{bubbles:true,cancelable:true,composed:true,' +
      'pointerId:23,pointerType:"mouse",button:0,clientX:x,clientY:y}));}' +
      'pe("pointerdown");' +
      'var on=c.classList.contains("dragging");' +
      'pe("pointerup");' +
      'var off=c.classList.contains("dragging");' +
      'w.classList.remove("mode-hidden");' +
      'return {on:on,off:off,wrapW:wrapW,pillW:pillW,hid:/mode-hidden/.test(w.className)};})()'
    );
    // 只测"按下那一下有没有人接"—— 不派 pointermove，所以不会真搬她、也不会写脏位置。
    // 改之前这一格必然红：pointerdown 的监听长在 card 上，而收起态 card 是 display:none。
    check('收成小入口后按下她就被接住了（拖拽把手活着），且隐形死区没了（wrap 宽等于小入口宽）',
      !!dragPill && dragPill.on === true && dragPill.off === false
      && dragPill.wrapW <= dragPill.pillW + 2 && dragPill.hid === false,
      JSON.stringify(dragPill).slice(0, 220));

    // ⑥ 她自己偶尔开口：四条"别说"各挡各的（第四条「标签页在后台」只能切真后台，见 ⑥-b）。
    //    ⚠️ 每个"闭嘴"断言前都要先把**别的**门槛拨到"该说话"（quiet() 把上次开口推到 200 秒前），
    //    否则"她没说"可能只是时间没到 —— 那就是把已知缺陷改坏了也照样绿的假绿。
    await ctx.client.send('Page.bringToFront');   // document.hidden 必须为 false，否则正例永远不成立
    var idle = await ctx.client.evaluate(
      '(function(){var h=document.getElementById("omitone-page-pet-host");' +
      'var sr=h.shadowRoot;var wrap=sr.getElementById("wrap");var c=sr.getElementById("card");' +
      'var b=sr.getElementById("bubble");' +
      // 把手是"拍一拍"的事件，**回执读气泡本身** —— 内容脚本与页面是两个 JS 世界，' +
      // 函数与数据都传不过来（只有 DOM 与属性共用）。
      'function tick(){b.textContent="";b.classList.remove("show");' +
      'h.dispatchEvent(new Event("omitone:pet-idle-tick"));' +
      'return {sp:/show/.test(String(b.className)),txt:String(b.textContent||"")};}' +
      'function quiet(){h.dataset.saidAt=String(Date.now()-200000);}' +
      // 自证：把"上次开口"拨到 200 秒前拍一下，气泡必须亮。不亮 = 监听器压根没挂上，
      // 下面每一条"她闭嘴"都会因此假绿 —— 先把它单独钉成一条前提断言。
      'var saved=String(h.dataset.saidAt||"");quiet();var probe=tick();' +
      'if(saved){h.dataset.saidAt=saved;}else{h.removeAttribute("data-said-at");}' +
      'if(probe.sp!==true)return {hook:false};' +
      'var o={hook:true,hidden:document.hidden};' +
      // 时间门槛：刚说过话（上面那一下就是"刚说过"）→ 不许插话。此时其它条件都允许说话。
      'o.freshQuiet=!tick().sp;' +
      // 被收起：拨到该说了，也必须闭嘴
      'quiet();wrap.classList.add("mode-hidden");o.hiddenQuiet=!tick().sp;' +
      'wrap.classList.remove("mode-hidden");' +
      // 正被拖着走：同上
      'quiet();c.classList.add("dragging");o.dragQuiet=!tick().sp;c.classList.remove("dragging");' +
      // 标签页在后台这一档**不在这个探针里**：内容脚本与页面是两个 JS world，
      // 在页面世界里给 `document` 挂 own `hidden` 属性，内容脚本那边读到的仍是原型上的 false
      // （实测：桩打上后"她照样说话"）。真把它翻成 hidden 只有一条路 —— 把**这一页所在的窗口**
      // 最小化（切另一个标签页不够，实测见下面 ⑥-b），自证 hidden 后单独一段跑。
      // 正例：安静够了 → 说一句，气泡真的亮，形状是一小块
      'quiet();var t=tick();var r=b.getBoundingClientRect();' +
      'o.line=t.txt;o.spoke=t.sp&&t.txt.length>0;' +
      'o.shape={w:Math.round(r.width),h:Math.round(r.height)};' +
      // 一句之后立刻又不说（否则 15 秒一拍 = 话痨）
      'o.onceOnly=!tick().sp;' +
      'o.saidRefreshed=(Number(h.dataset.saidAt)>Date.now()-3000);' +
      'b.classList.remove("show");return o;})()'
    );
    check('前提：自动台词的把手真的通（拨旧时间戳拍一下，气泡必须亮）',
      !!idle && idle.hook === true && idle.hidden === false, JSON.stringify(idle).slice(0, 160));
    check('她自己开口只在该开口时：刚说过/被收起/正拖着 → 三种都闭嘴；安静够了 → 说一句且只一句',
      !!idle && idle.freshQuiet === true && idle.hiddenQuiet === true && idle.dragQuiet === true &&
      idle.spoke === true && idle.onceOnly === true && idle.saidRefreshed === true,
      JSON.stringify(idle).slice(0, 300));
    check('自动台词那口气的形状也是一小块横排（不是竖条）',
      !!idle && !!idle.shape && idle.shape.w >= 88 && idle.shape.h <= 62 && idle.shape.w > idle.shape.h,
      JSON.stringify(idle && idle.shape));

    // ⑥-c 台词的**时段桶**（批次 64：用户「吉祥物的话有点单一和少了」）。
    //     ⚠️ 探针必须把钟点钉死（detail.hour）：不钉的话测的是本机时钟，
    //        凌晨跑和下午跑拿到的池子不一样，红了也不知道是代码坏了还是天亮了。
    //     读回来的是宿主 dataset 上的**归因格**（内容脚本写的）—— 两个 JS world 只有 DOM 共用，
    //        页面世界读不到 SAY 那张表，所以这里比的是"桶名 + 句子与归因格同源 + 桶间/连拍不重样"，
    //        句子内容本身由 omitone-pet-game-test.cjs 的规则层那几十项钉住。
    var idleCtx = await ctx.client.evaluate(
      '(function(){var h=document.getElementById("omitone-page-pet-host");' +
      'var sr=h.shadowRoot;var wrap=sr.getElementById("wrap");var c=sr.getElementById("card");' +
      'var b=sr.getElementById("bubble");' +
      'function tickAt(hour){b.textContent="";b.classList.remove("show");' +
      'h.dataset.sayPeriod="";h.dataset.sayLine="";h.dataset.sayFam="";h.dataset.sayBand="";' +
      'h.dispatchEvent(new CustomEvent("omitone:pet-idle-tick",{detail:{hour:hour}}));' +
      'return {sp:/show/.test(String(b.className)),txt:String(b.textContent||"")+"" ,' +
      'per:String(h.dataset.sayPeriod||""),line:String(h.dataset.sayLine||""),' +
      'fam:String(h.dataset.sayFam||""),band:String(h.dataset.sayBand||"")};}' +
      'function quiet(){h.dataset.saidAt=String(Date.now()-200000);}' +
      // 前提自证：三条会让她闭嘴的闸此刻都得是"允许说话"的形状，否则下面全是假绿
      'var o={hidden:document.hidden,drag:c.classList.contains("dragging"),' +
      'coll:wrap.classList.contains("mode-hidden")};' +
      'quiet();o.dawn=tickAt(2);quiet();o.midday=tickAt(12);quiet();o.night=tickAt(23);' +
      // 同一桶连着两拍：上一句被排除掉，才会真的换一句
      'quiet();var first=tickAt(15);quiet();o.repeat={first:first.txt,second:tickAt(15).txt};' +
      // 连着 24 拍（每拍都先"安静够久"）：两族并池之后要说得出"阶段那族真的走到过"，
      //   也要数得出"最近三句不重样"。24 而不是 12：阶段那族在并池里占 5/9，
      //   12 拍全躲开它的概率还有万分之几 —— 这不是洁癖，是这一族红一次就要人重跑一整趟。
      'o.series=[];o.fams={};o.bandSeen={};o.stall=null;' +
      'for(var i=0;i<24;i++){quiet();var s=tickAt(20);' +
      'if(!s.sp||!s.txt){o.stall={i:i,sp:!!s.sp,fam:s.fam};break;}' +
      'o.series.push(s.txt);o.fams[s.fam]=(o.fams[s.fam]||0)+1;' +
      'o.bandSeen[s.band]=(o.bandSeen[s.band]||0)+1;}' +
      'b.classList.remove("show");return o;})()'
    );
    check('前提：这一趟三条"别说"闸都是开着的，且探针拍子真的落地（凌晨那一格必须亮）',
      !!idleCtx && idleCtx.hidden === false && idleCtx.drag === false && idleCtx.coll === false &&
      idleCtx.dawn && idleCtx.dawn.sp === true && idleCtx.dawn.txt.length > 0,
      JSON.stringify(idleCtx).slice(0, 200));
    check('她按时间说话：凌晨/中午/深夜三个钟点各自落在说好的那一格，归因格与气泡同源',
      !!idleCtx && idleCtx.dawn.per === 'dawn' && idleCtx.midday.per === 'midday' &&
      idleCtx.night.per === 'night' && idleCtx.midday.sp === true && idleCtx.night.sp === true &&
      idleCtx.dawn.line === idleCtx.dawn.txt && idleCtx.midday.line === idleCtx.midday.txt &&
      idleCtx.night.line === idleCtx.night.txt,
      JSON.stringify(idleCtx).slice(0, 400));
    check('三个时段是三句不同的话（不再翻来覆去那一句）',
      !!idleCtx && idleCtx.dawn.txt !== idleCtx.midday.txt &&
      idleCtx.midday.txt !== idleCtx.night.txt && idleCtx.dawn.txt !== idleCtx.night.txt,
      JSON.stringify([idleCtx.dawn.txt, idleCtx.midday.txt, idleCtx.night.txt]));
    check('同一时段连着两拍也不重样（规则层的"上一句"真的接进了页面这一侧）',
      !!idleCtx && idleCtx.repeat.first.length > 0 && idleCtx.repeat.second !== idleCtx.repeat.first,
      JSON.stringify(idleCtx.repeat));

    // ⑥-c2 好感阶段那一族（批次 104：用户「不同阶段的对话也分化一下」）。
    //     ⚠️ 页面世界读不到 SAY 那张表（隔离区），所以这里比的还是**归因格**：
    //       `sayFam` 说这一句抽自哪一族、`sayBand` 说当时是哪一阶段 —— 两格都由内容脚本在
    //       **气泡真亮之后**才写，所以"两族都走到过"读的是真开口，不是计数器。
    //     ⚠️ `band` 必须是三格之一：那一格空串意味着等级没读回来（老档／存档没到位），
    //       这时阶段那族**按设计不参与**（不许把"不知道熟不熟"猜成生分话），
    //       拿它当"两族都走到"的现场会是一次假绿。
    var idleSeries = (idleCtx && idleCtx.series) || [];
    var idleRecentDup = [];
    for (var si = 3; si < idleSeries.length; si++) {
      if (idleSeries.slice(si - 3, si).indexOf(idleSeries[si]) >= 0) idleRecentDup.push(si + ':' + idleSeries[si]);
    }
    check('前提：连着 24 拍每一拍都真亮了、也真说了话（中途闭嘴就把卡住的那一拍报出来）',
      !!idleCtx && idleCtx.stall === null && idleSeries.length === 24,
      JSON.stringify(idleCtx && (idleCtx.stall || { n: idleSeries.length })));
    check('这一页的好感阶段读得回来（new/close/deep 三格之一；空串=等级没到位，下面两条不许当证据）',
      ['new', 'close', 'deep'].indexOf(idleCtx && idleCtx.dawn.band) >= 0 &&
      ['new', 'close', 'deep'].indexOf(idleCtx && idleCtx.midday.band) >= 0,
      JSON.stringify(idleCtx && { dawn: idleCtx.dawn.band, fams: idleCtx.fams }));
    check('熟不熟听得出来：24 拍里阶段那族与时段那族都开口过，且每一拍归因只落在这两格里',
      !!idleCtx && (idleCtx.fams.bond || 0) >= 1 && (idleCtx.fams.period || 0) >= 1 &&
      (idleCtx.fams.bond || 0) + (idleCtx.fams.period || 0) === 24,
      JSON.stringify(idleCtx && idleCtx.fams));
    check('最近三句之内不重样（并池之后只挡上一句会隔一句卡带，⑥-c 那条三时段断言也会随机红）',
      idleSeries.length === 24 && idleRecentDup.length === 0,
      JSON.stringify(idleRecentDup.slice(0, 3)));

    // ⑥-d 大事那几句在**页面这一侧**也点名得到（批次 65：升级／成就以前是两处各抄一句拼接）。
    //     存档从写入器（那一枚 `?ui=lite` 的扩展页）拨过来：主世界读不到 chrome.storage，
    //     但 content.js 监听 omitonePetBond 的改动并把新档换进内存，拨完等一拍她就换档。
    //     ⚠️ 每一趟把 `omitoneStudyStats.activeSeconds` 一起钉成 0：页面摸头之后会 `settleStudyIntoBond`，
    //        统计层里留着别的情景写进去的时长就会**顺手再升一级**，那一级的 levelup 会把
    //        这一趟要验的成就／普通摸头盖掉 —— 那时"她说了哪一族"读回来的就不是我要的那一个。
    //     ⚠️ 三次点击各等 2.2 秒：2 秒内连戳三下会走「躲开」那一族，说出来的就不是这三句了。
    var cwPet = await initConfigWriter(ctx.extensionId);
    var setBond = async function (over) {
      await cwPet.evaluate(
        'new Promise(function (res) {' +
        'var g = self.OmitonePetGame; var k = g.dayKeyOf(Date.now());' +
        'var b = { affection: 0, day: k, patsToday: 0, studyPointsToday: 0, countedSeconds: 0,' +
        ' totalPats: 0, totalStudyMinutes: 0, nightPats: 0, streakDays: 1, lastMetDay: k, ach: {} };' +
        'var over = ' + JSON.stringify(over) + ';' +
        'for (var key in over) b[key] = over[key];' +
        // 成就要点全：从规则层读回全部 id（别手抄清单 —— 以后再加成就不该再红这一格）
        'if (b.allLit) { var litIds = g.ACHIEVEMENTS.map(function (a) { return a.id; });' +
        '  for (var li = 0; li < litIds.length; li++) b.ach[litIds[li]] = k; delete b.allLit; }' +
        'chrome.storage.local.set({ omitonePetBond: b, omitoneStudyStats:' +
        ' { date: k, activeSeconds: 0, lastActiveAt: Date.now(), lastFlushAt: Date.now() } },' +
        ' function () { res(true); }); })'
      );
      await sleep(500);   // onChanged → 页面里那一份内存
    };
    var patOnce = async function () {
      await sleep(2200);
      return await ctx.client.evaluate(
        '(function(){var h=document.getElementById("omitone-page-pet-host");' +
        'var sr=h.shadowRoot;var b=sr.getElementById("bubble");var lv=sr.getElementById("level");' +
        'b.textContent="";b.classList.remove("show");' +
        'sr.getElementById("petImg").click();' +
        'return {sp:/show/.test(String(b.className)),bubble:String(b.textContent||""),' +
        'from:String(h.dataset.sayFrom||""),attr:String(h.dataset.sayLine||""),' +
        'per:String(h.dataset.sayPeriod||""),title:String(lv.getAttribute("title")||"")};})()'
      );
    };
    await setBond({ affection: 14, totalPats: 0 });
    var bigLevel = await patOnce();
    await setBond({ affection: 40, totalPats: 99 });
    var bigAch = await patOnce();
    // 全部成就从规则层读回 id、记成"已经点亮"→ 这一摸既跨不过级也没有新成就，只剩本级摸头话那一族
    await setBond({ affection: 40, totalPats: 120, allLit: true });
    var bigPat = await patOnce();
    var affOf = function (r) {
      var m = /好感度\s*(\d+)/.exec((r && r.title) || '');
      return m ? Number(m[1]) : -1;
    };
    check('前提：页面这三摸她都开了口，而且每一摸都登记了"哪一族"（三条点名断言的前提）',
      !!bigLevel && !!bigAch && !!bigPat &&
      [bigLevel, bigAch, bigPat].every(function (r) { return r.sp === true && r.from.length > 0 && r.bubble.length > 0; }),
      JSON.stringify({ level: bigLevel, ach: bigAch, pat: bigPat }));
    check('跨级那一摸点名 levelup：好感从 14 走到 15（读回来的是徽章 title 里那个数）、气泡与归因格同源',
      !!bigLevel && bigLevel.from === 'levelup' && affOf(bigLevel) === 15 &&
      bigLevel.attr === bigLevel.bubble, JSON.stringify(bigLevel));
    check('点亮成就那一摸点名 achievement（这一摸没跨级：40→41）',
      !!bigAch && bigAch.from === 'achievement' && affOf(bigAch) === 41 &&
      bigAch.attr === bigAch.bubble, JSON.stringify({ ach: bigAch, lvl: bigLevel.from }));
    check('都点亮过之后普通一摸点名 pat（三族在页面侧各走各的，不是写死同一个常量）',
      !!bigPat && bigPat.from === 'pat' && bigPat.attr === bigPat.bubble &&
      bigPat.from !== bigLevel.from && bigPat.from !== bigAch.from, JSON.stringify(bigPat));
    check('页面这三句都不许留没填的占位／undefined／空的「」',
      [bigLevel, bigAch, bigPat].every(function (r) {
        return !!r && !/\{/.test(r.bubble) && !/undefined/.test(r.bubble) && !/「」/.test(r.bubble);
      }), JSON.stringify([bigLevel.bubble, bigAch.bubble, bigPat.bubble]));
    check('平池那三族的时段格必须是空串（"这一句是哪个钟点格抽的"对它们没意义）',
      [bigLevel, bigAch, bigPat].every(function (r) { return !!r && r.per === ''; }),
      JSON.stringify([bigLevel.per, bigAch.per, bigPat.per]));

    // ⑥-b 「标签页在后台」这一档 —— 只能切**真**后台（批次 39，全量跑改法见批次 41）。
    //     页面世界与内容脚本是两个 JS world：在页面世界里给 `document` 挂 own `hidden`
    //     属性，内容脚本读到的仍是原型上的 false（实测打桩后"她照样说话"，那条断言恒绿）。
    //     真翻 hidden 只有一条路：把**同一扇窗口的另一个标签**端成活动标签（`activateTab`，
    //     实测 0~19 毫秒翻）。批次 39 是「随手开一个新标签再激活」—— 只有一扇窗口时管用，
    //     全量跑却不翻（实测 tabs 3→4、flipMs -1）：那一发新标签开去了**别的窗口**，
    //     这一页仍是自己窗口的活动标签。所以这里先查窗口、再动作，两头都自证。
    //     ⚠️ 试过的两条死路：① `Browser.setWindowBounds {state:'minimized'}` 在这台 Edge 上
    //        回 `result:{}` 却纹丝不动（批次 47 带回读再量一次：`windowState` 仍是 normal、
    //        bounds 一动不动，hidden 也不翻）；② 在页面世界里改 `document.hidden` —— 内容脚本压根读不到。
    //     ⚠️ **沙盒那台 Edge 端不动标签的根因在启动参数上**（批次 47 逐特性量出来的）：
    //        不加 `--disable-features=CalculateNativeWinOcclusion` 时，同窗口把另一枚端上去
    //        `hasFocus` 正确翻过去了，可两枚的 `document.hidden` 都恒为 false（实测 flip=-1）；
    //        加上它，同一发操作 200 毫秒就翻成 hidden=true。开关在 omitone-sandbox.cjs 的 launchEdge。
    //     ⚠️ **可见性要在排拍子之前就位，读完再核一次**：批次 41 第一版是"先排拍子再切窗口"，
    //        前台对照那趟读到 `hidden=true`（这扇窗口会被别的东西压住，OS 层遮挡同样算 hidden）——
    //        "她没说话"和"这趟压根不在要求的那一档里"就同形了。所以每一趟先站好位、再拍一次、
    //        读回来不对就整趟重来（最多三趟）；三趟都稳不住才判失败。
    //     ⚠️ 后台标签页的 setTimeout 被节流到最小 1 秒 → 排程 1600ms、节点侧等到 3400ms。
    //     ⚠️ **必须配对跑一个同样排程、但不切后台的对照**：少了它，"气泡没亮"可能只是
    //        定时器压根没跑。而且两趟都在页面世界里数拍子有没有真落地（`__pkTicks`），
    //        `tickFired < 1` 一样整趟重来 —— 否则"她闭嘴"和"定时器被节流到没跑"同形。
    //     读结果在**仍是后台时**用 CDP 读（evaluate 不抢焦点）：唤回前台再读的话，
    //     她自己那条 15 秒 interval 可能正好插进来点亮气泡，把"该闭嘴"验成"说话了"。
    var bgPlan = null;
    var readHidden = async function () {
      return await ctx.client.evaluate('(function(){return document.hidden;})()');
    };
    /** 轮询到要求的那一档为止；返回耗时（毫秒），没等到返回 -1 —— 只报实测，不报自认为的成功。 */
    var untilHidden = async function (want, rounds) {
      var t0 = Date.now();
      var n = rounds || 14;
      for (var i = 0; i < n; i++) {
        if ((await readHidden()) === want) return Date.now() - t0;
        await sleep(150);
      }
      return -1;
    };
    // 找「和这一页同一扇窗口」的接管标签，**全部收下来**（批次 45：以前只留第一枚）。
    // 只有一枚候选时够用；全量跑里那一枚（配置写入器 popup）实测端不动这一页，
    // 于是整场恒红 —— 而"哪一枚能动"事先并不知道，只能逐枚试、每枚自证。
    // ⚠️ cdp:false 必须单独报出来：withBrowserClient 连不上时返回 null，
    //    旧写法把它当成"没有候选"，于是"沙盒没把真实调试端口灌进来"长得和"这扇窗口里没有别的标签"一样。
    //    这里再分一刀：ctx.targetId 没有 → 那一次 Browser.getWindowForTarget 直接抛，
    //    外面看也只是 cdp:false（批次 47 在沙盒里就是这一族，两个红折腾了两轮）。
    var findStandIn = async function () {
      var plan = { win: null, cands: [], opened: null, cdp: false, haveTargetId: !!ctx.targetId };
      if (!ctx.targetId) return plan;
      var got = await withBrowserClient(async function (bc) {
        var infos = ((await bc.send('Target.getTargets')) || {}).targetInfos || [];
        var pages = infos.filter(function (x) { return x.type === 'page'; });
        var wa = await bc.send('Browser.getWindowForTarget', { targetId: ctx.targetId });
        plan.cdp = true;
        plan.win = (wa && wa.windowId) || null;
        var sameWin = async function (tid) {
          var w = await bc.send('Browser.getWindowForTarget', { targetId: tid });
          return !!w && w.windowId === plan.win;
        };
        for (var i = 0; i < pages.length && plan.cands.length < 4 && i < 16; i++) {
          if (pages[i].targetId === ctx.targetId) continue;
          if (await sameWin(pages[i].targetId)) {
            plan.cands.push({ id: pages[i].targetId, url: String(pages[i].url || '').replace(/^https?:\/\//, '').slice(0, 34) });
          }
        }
        return plan;
      });
      return got || plan;
    };
    /** 用 CDP 的 Target.activateTarget 端一枚标签（成功返回 true，失败返回错误串，让它进载荷别吞）。 */
    var activateCdp = async function (tid) {
      var r = await withBrowserClient(async function (bc) {
        try { await bc.send('Target.activateTarget', { targetId: tid }); return true; }
        catch (e) { return String((e && e.message) || e).slice(0, 60); }
      });
      return r === true ? true : (r === null ? '浏览器级连接没连上' : r);
    };
    /**
     * 把这一页挤下后台 = 把同窗口另一枚标签端成活动标签，并轮询到 hidden===true 为止。
     * ⚠️ 每一枚都要**实测** hidden 翻没翻：activateTab 回 true 只说明 HTTP 成功，
     *    不说明这一页真的下后台（批次 45 全量跑就是这个：候选找到了、请求发出去了，hidden 不动）。
     *    现成的四枚都端不动才新开一枚 —— 新开之前必须先把这一页端到最前，
     *    否则新标签会开去别的窗口（批次 39 的恒红就是这么来的）。
     */
    var pushBehind = async function () {
      if (!bgPlan) bgPlan = await findStandIn();
      var tried = [];
      var list = (bgPlan.cands || []).slice(0, 4);
      for (var i = 0; i < list.length; i++) {
        // 两条路都试：`/json/activate`（HTTP，现场实测有效）与 `Target.activateTarget`（CDP）。
        // 沙盒那台 Edge 用 HTTP 那条端不动（批次 47 实测：ok:true、focus 也真过去了，
        // 但这一页的 document.hidden 纹丝不动），所以必须逐条实测，不能把"请求成功"当"端上了"。
        var a1 = await activateCdp(list[i].id);
        var m1 = await untilHidden(true, 5);
        tried.push({ k: '现成/CDP', u: list[i].url, ok: a1 === true, ms: m1 });
        if (m1 >= 0) return { win: bgPlan.win, cdp: bgPlan.cdp, noId: !bgPlan.haveTargetId, cand: list[i].id, opened: bgPlan.opened, flipMs: m1, how: '端标签(CDP)', tried: tried };
        var ok = await activateTab(list[i].id);
        var ms = await untilHidden(true, 5);
        tried.push({ k: '现成/HTTP', u: list[i].url, ok: ok, ms: ms });
        if (ms >= 0) return { win: bgPlan.win, cdp: bgPlan.cdp, noId: !bgPlan.haveTargetId, cand: list[i].id, opened: bgPlan.opened, flipMs: ms, how: '端标签(HTTP)', tried: tried };
      }
      await ctx.client.send('Page.bringToFront').catch(function () {});
      // 上一趟新开的那枚还挂着就先关掉（整轮只留一枚，否则三趟重试会攒出三枚空白标签抢焦点）
      if (bgPlan.opened) {
        await closeTab(bgPlan.opened).catch(function () {});
        bgPlan.opened = null;
      }
      var fresh = await withBrowserClient(async function (bc) {
        var r = await bc.send('Target.createTarget', { url: 'about:blank' });
        var tid = r && r.targetId;
        if (!tid) return null;
        var w = await bc.send('Browser.getWindowForTarget', { targetId: tid });
        return w && w.windowId === bgPlan.win ? tid : null;
      });
      var ms2 = -1;
      if (fresh) {
        bgPlan.opened = fresh;
        var ok2 = await activateTab(fresh);
        ms2 = await untilHidden(true, 10);
        tried.push({ k: '新开', u: 'about:blank', ok: ok2, ms: ms2 });
        if (ms2 >= 0) {
          return { win: bgPlan.win, cdp: bgPlan.cdp, noId: !bgPlan.haveTargetId, cand: fresh, opened: fresh, flipMs: ms2, how: '端标签', tried: tried };
        }
      } else {
        tried.push({ k: '新开', u: '(开去了别的窗口)', ok: false, ms: -1 });
      }
      /**
       * 端标签两级都没翻起来 —— 把这趟试过的每一枚连实测一起交回去，别只报一个 false。
       * ⚠️ 别再往这里加机制：批次 47 逐条量过这台 Edge（Edg/157.0.4341.46）还剩的两条路
       *    都是死的 —— ① `Browser.setWindowBounds {state:'minimized'}` 不抛错，但回读
       *       `windowState` 仍是 `normal`、bounds 一动不动（批次 41 也是这个结果，两次实测）；
       *    ② 协议里**没有**可见性覆盖方法：`Emulation.setVisibilityStateOverride` /
       *       `Emulation.clearVisibilityStateOverride` / `Page.setVisibilityOverride` /
       *       `Page.setPageVisibility` 全部回 "wasn't found"，只有 `Page.setWebLifecycleState
       *       {state:'frozen'}` 能读出 hidden:true —— 可 frozen 把 JS 执行整个冻住，
       *       那就不是"在后台"而是"停了"，用它等于把"她没说话"验成"代码没跑"。
       *    真的开关在**启动参数**上：`--disable-features=CalculateNativeWinOcclusion`
       *    （见 omitone-sandbox.cjs 的 launchEdge），加上它同窗口激活 200 毫秒就翻。
       */
      return {
        win: bgPlan.win, cdp: bgPlan.cdp, noId: !bgPlan.haveTargetId,
        cand: fresh || null, opened: bgPlan.opened, flipMs: -1,
        how: '端标签两级都没翻', tried: tried
      };
    };
    /** 唤回：关掉这趟新开的接管标签，再端到最前，轮询到 hidden===false 为止。 */
    var wakeUp = async function () {
      if (bgPlan && bgPlan.opened) {
        await closeTab(bgPlan.opened);
        bgPlan.opened = null;
      }
      await ctx.client.send('Page.bringToFront').catch(function () {});
      return await untilHidden(false) >= 0;
    };

    var readPet = async function () {
      return await ctx.client.evaluate(
        '(function(){var h=document.getElementById("omitone-page-pet-host");' +
        'var b=h.shadowRoot.getElementById("bubble");' +
        'var spoke=/show/.test(String(b.className));var txt=String(b.textContent||"");' +
        'b.classList.remove("show");' +
        'return {hidden:document.hidden,spoke:spoke,txt:txt,ticks:window.__pkTicks};})()'
      );
    };
    var petIdleOnce = async function (toBackground) {
      var want = !!toBackground;
      var run = async function () {
        var beforeSwitch = await readHidden();
        var how = toBackground ? await pushBehind() : { woke: await wakeUp() };
        var at = await ctx.client.evaluate(
          '(function(){var h=document.getElementById("omitone-page-pet-host");' +
          'var b=h.shadowRoot.getElementById("bubble");' +
          'b.textContent="";b.classList.remove("show");' +
          // 拍子计数器：主世界也挂一个监听，只数"这一记拍子真的派发到 host 上了"
          'if(typeof window.__pkTicks!=="number")window.__pkTicks=0;' +
          'if(!window.__pkTickHooked){window.__pkTickHooked=1;' +
          ' h.addEventListener("omitone:pet-idle-tick",function(){window.__pkTicks++;});}' +
          'var fired=window.__pkTicks;' +
          // 时间门槛拨到"该说话"（200 秒没开口），只剩这一档（后台/前台）在起作用
          'h.dataset.saidAt=String(Date.now()-200000);' +
          'setTimeout(function(){h.dispatchEvent(new Event("omitone:pet-idle-tick"));},1600);' +
          'return {hidden:document.hidden,fired:fired};})()'
        );
        var t0 = Date.now();
        await sleep(Math.max(700, 3400 - (Date.now() - t0)));
        var out = await readPet();
        out.beforeSwitch = beforeSwitch;
        out.atSchedule = at && at.hidden;
        out.how = how;
        out.tickFired = (typeof out.ticks === 'number' ? out.ticks : 0) - (Number(at && at.fired) || 0);
        return out;
      };
      var out = null, attempts = 0;
      while (attempts < 3) {
        attempts++;
        out = await run();
        // 这一趟算不算数：拍子真落地了 + 排的时候和读的时候都在要求的那一档可见性上
        if (out.tickFired >= 1 && out.atSchedule === want && out.hidden === want) break;
      }
      out.attempts = attempts;
      out.flipMs = out.how && typeof out.how.flipMs === 'number' ? out.how.flipMs : -1;
      // 后台那趟测完就唤回 —— ⑦ 真鼠标和后面的场景都要求这一页在前台，
      // 唤没唤回由下面「独立回读」那条前提验收，不由这里自报。
      if (want) out.back = await wakeUp();
      return out;
    };
    var bgIdle = await petIdleOnce(true);
    // 唤回这件事**独立回读一次**再看：`wakeUp` 自己报的布尔只说明"它轮询到了"，
    // 而这一页后来可能被别的东西压回去 —— ⑦ 真鼠标与前台对照都建立在"已经回到前台"上。
    var hiddenAfterBg = await readHidden();
    var fgIdle = await petIdleOnce(false);
    check('前提：这一页真的被挤到后台了（切之前 hidden=false、排拍子时与读完时都还是 hidden=true）' +
      '—— 没这一步，"她闭嘴"等于没测',
      !!bgIdle && bgIdle.beforeSwitch === false && bgIdle.atSchedule === true &&
      bgIdle.hidden === true && bgIdle.flipMs >= 0,
      JSON.stringify(bgIdle && {
        before: bgIdle.beforeSwitch, at: bgIdle.atSchedule, after: bgIdle.hidden,
        flipMs: bgIdle.flipMs, attempts: bgIdle.attempts,
        win: bgIdle.how && bgIdle.how.win,
        cdp: bgIdle.how && bgIdle.how.cdp,
        noId: bgIdle.how && bgIdle.how.noId,
        via: bgIdle.how && bgIdle.how.how,
        cand: !!(bgIdle.how && bgIdle.how.cand),
        tried: bgIdle.how && bgIdle.how.tried
      }).slice(0, 220));
    check('前提收尾：这一页真的唤回前台了（**独立回读** document.hidden，不信任唤回函数自己报的那个数）' +
      '—— 回不去的话 ⑦ 真鼠标与前台对照全建在"还在后台"上',
      hiddenAfterBg === false && !!bgIdle && bgIdle.back === true,
      JSON.stringify({ hiddenNow: hiddenAfterBg, back: bgIdle && bgIdle.back, how: bgIdle && bgIdle.how }).slice(0, 620));
    check('标签页在后台时她不插话，回到前台同一拍就说（旧写法在页面世界打桩 document.hidden，内容脚本读不到，恒绿）' +
      '—— 两趟都自证那一拍真的派发到 host 上，且可见性全程站在要求的那一档（不稳就整趟重来，最多三趟）',
      !!bgIdle && !!fgIdle && bgIdle.spoke === false && bgIdle.txt === '' &&
      fgIdle.atSchedule === false && fgIdle.hidden === false && fgIdle.spoke === true && fgIdle.txt.length > 0,
      JSON.stringify({ bg: bgIdle, fg: fgIdle }).slice(0, 300));

    // ⑦ 真鼠标点得动（2026-11-12 现场）。①–⑥ 全是 dispatchEvent / .click()，
    //    而 pointerdown 里那句 setPointerCapture 会把兼容的 mousedown/mouseup/click
    //    **一起改派给捕获目标（card）** —— 挂在立绘上的摸头监听收不到真点击，
    //    合成事件却照样全绿。用户报的「刷课页吉祥物不能互动了」就是这么来的：
    //    悬停、拖动都真在动，只有"摸她一下"死的。只有 CDP Input 域能测到这一条。
    //    ⚠️ 数 .pat 用观察器计数，不用"读当下 class"：那一个 class 只活 480ms，
    //    比的是几个 CDP 往返的快慢，不是行为 —— 现场踩过一次假阴性。
    var patPt = await ctx.client.evaluate(
      '(function(){var h=document.getElementById("omitone-page-pet-host");' +
      'var i=h.shadowRoot.getElementById("petImg");var r=i.getBoundingClientRect();' +
      'window.__pat=0;' +
      'if(!window.__patObs){window.__patObs=new MutationObserver(function(){' +
      'if(i.classList.contains("pat"))window.__pat++;});' +
      'window.__patObs.observe(i,{attributes:true,attributeFilter:["class"]});}' +
      'Array.prototype.forEach.call(h.shadowRoot.querySelectorAll(".heart"),function(x){x.remove();});' +
      'return {x:Math.round(r.left+r.width/2),y:Math.round(r.top+r.height/2),pat:window.__pat,' +
      'hostLeft:Math.round(h.getBoundingClientRect().left)};})()'
    );
    await ctx.client.send('Input.dispatchMouseEvent', { type: 'mousePressed', x: patPt.x, y: patPt.y, button: 'left', buttons: 1, clickCount: 1 });
    await ctx.client.send('Input.dispatchMouseEvent', { type: 'mouseReleased', x: patPt.x, y: patPt.y, button: 'left', buttons: 0, clickCount: 1 });
    var trusted = await ctx.client.evaluate(
      '(function(){var h=document.getElementById("omitone-page-pet-host");var sr=h.shadowRoot;' +
      'var b=sr.getElementById("bubble");' +
      'return {patSeen:window.__pat,hearts:sr.querySelectorAll(".heart").length,' +
      'spoke:/show/.test(String(b.className||"")),txt:String(b.textContent||"").slice(0,20)};})()'
    );
    check('真鼠标（CDP Input 域）点她也摸头：pat 挂上过、心形冒出、气泡有回执 —— 合成事件测不到这一条',
      !!trusted && trusted.patSeen > patPt.pat && trusted.hearts > 0 && trusted.spoke === true,
      JSON.stringify(trusted) + ' @' + JSON.stringify(patPt));

    // ⑧ 配对：改成"越过 6px 才捕获"之后，真·拖动那一下仍然不许摸头 ——
    //    否则拖她一次就白涨一次好感，等于把"放哪儿"变成了"刷好感"。
    //    拖出去再原路拖回（净位移 0），并把 inline 位置清回默认锚点。
    async function dragPt(pt, ddx) {
      await ctx.client.send('Input.dispatchMouseEvent', { type: 'mousePressed', x: pt.x, y: pt.y, button: 'left', buttons: 1, clickCount: 1 });
      for (var s = 1; s <= 4; s++) {
        await ctx.client.send('Input.dispatchMouseEvent', { type: 'mouseMoved', x: pt.x + Math.round(ddx * s / 4), y: pt.y, button: 'left', buttons: 1, clickCount: 0 });
      }
      await ctx.client.send('Input.dispatchMouseEvent', { type: 'mouseReleased', x: pt.x + ddx, y: pt.y, button: 'left', buttons: 0, clickCount: 1 });
    }
    await ctx.client.evaluate(
      '(function(){var h=document.getElementById("omitone-page-pet-host");' +
      'Array.prototype.forEach.call(h.shadowRoot.querySelectorAll(".heart"),function(x){x.remove();});return true;})()'
    );
    var patBeforeDrag = await ctx.client.evaluate('window.__pat|0');
    await dragPt(patPt, 60);
    var dragged = await ctx.client.evaluate(
      '(function(){var h=document.getElementById("omitone-page-pet-host");var sr=h.shadowRoot;' +
      'var c=sr.getElementById("card"),i=sr.getElementById("petImg"),b=sr.getElementById("bubble");' +
      'var r=h.getBoundingClientRect();' +
      'return {patAdded:window.__pat,hearts:sr.querySelectorAll(".heart").length,' +
      'dragClass:c.classList.contains("dragging"),movedX:Math.round(r.left-' + patPt.hostLeft + '),' +
      'txt:String(b.textContent||"").slice(0,20)};})()'
    );
    check('真·拖动仍然不摸头（拖一次不许白涨一次好感），拖完 dragging 已摘、她确实跟着走',
      !!dragged && dragged.patAdded === patBeforeDrag && dragged.hearts === 0 &&
      dragged.dragClass === false && dragged.movedX === 60,
      JSON.stringify(dragged) + ' 拖前 pat 计数=' + patBeforeDrag);
    // 原路拖回 + 清回默认锚点，别把位置脏留给后面的场景
    await dragPt({ x: patPt.x + 60, y: patPt.y }, -60);
    await ctx.client.evaluate(
      '(function(){var h=document.getElementById("omitone-page-pet-host");' +
      'h.style.left="";h.style.top="";h.style.right="84px";h.style.bottom="176px";' +
      'Array.prototype.forEach.call(h.shadowRoot.querySelectorAll(".heart"),function(x){x.remove();});return true;})()'
    );

    // ⑨ 拖动被中途打断（pointercancel）那一发到底算不算一次真收尾 —— 批次 178 / 队 #62。
    //    成因不是推的：真实鼠标探针量到「原生拖拽接管」那一族派的是 dragstart → pointercancel，
    //    **之后不再有 pointerup**（`.workbuddy/probe62.log` 的 G 组：把 img 的 draggable=false 摘掉）；
    //    而 pointermove 早就把视觉与 `pagePet.pos` 挪走了（content.js:2927）——
    //    存档不跟上就是「这一页她在新地方，刷新一次弹回老地方」。
    //    六格各钉这个裁决的一面，摘掉任一半都只红该红那一格：
    //      ⑨-a 位置跟手、dragging 摘掉（打断不等于把她丢在半路）
    //      ⑨-b 不说话，而 pointerup 那一路照旧说话（同一发里的正控，不许把 endDrag 整条搬过来）
    //      ⑨-c 存档里那一格 == 屏幕上那一点（不许什么都不写；也不许只写内存）
    //      ⑨-d 打断之后摸头仍然响应（不许顺手把 suppressPatUntil 拨上——那是给 click 用的）
    //      ⑨-e 刷新一次不再弹回默认锚点（用户看得见的那一下，也是 ⑨-c 的症状面）
    //      ⑨-f 场景自己把写过的落点存档收干净
    //    接点按现场形状打在**立绘**上（notes/field-pet-shape-1123.md：host/.wrap/.card/.level
    //    全是 pointer-events:none，唯一 auto 的是 img），事件冒泡到 wrap 的那三个 handler。
    var POS_KEY = 'omitonePagePetPos';
    var pointerStep = '(function(){var h=document.getElementById("omitone-page-pet-host");' +
      'var sr=h.shadowRoot,i=sr.getElementById("petImg");' +
      'window.__pe62=function(t,px,py){i.dispatchEvent(new PointerEvent(t,{bubbles:true,cancelable:true,composed:true,' +
      'pointerId:41,pointerType:"mouse",isPrimary:true,button:0,' +
      'buttons:(t==="pointercancel"||t==="pointerup")?0:1,clientX:px,clientY:py}));};return true;})()';
    await ctx.client.evaluate(pointerStep);
    // 先做正控：pointerup 那一路必须照旧说话，否则 ⑨-b 的"cancel 不说话"就只是"没人说话"
    var upControl = await ctx.client.evaluate(
      '(function(){var h=document.getElementById("omitone-page-pet-host");var sr=h.shadowRoot;' +
      'var b=sr.getElementById("bubble");b.textContent="";b.classList.remove("show");' +
      'var r=h.getBoundingClientRect(),x=r.left+30,y=r.top+30;' +
      'window.__pe62("pointerdown",x,y);window.__pe62("pointermove",x-60,y);window.__pe62("pointerup",x-60,y);' +
      'return {spoke:/show/.test(String(b.className||"")),txt:String(b.textContent||"").slice(0,14)};})()'
    );
    // pointerup 那一发把 suppressPatUntil 拨到 now+260；等它过期，下面 cancel 后的摸头才归 cancel 自己负责
    await sleep(500);
    var patBeforeCancel = await ctx.client.evaluate('window.__pat|0');
    var cancelCase = await ctx.client.evaluate(
      '(function(){var h=document.getElementById("omitone-page-pet-host");var sr=h.shadowRoot;' +
      'var c=sr.getElementById("card"),b=sr.getElementById("bubble");' +
      'b.textContent="";b.classList.remove("show");' +
      'var r=h.getBoundingClientRect(),x=r.left+30,y=r.top+30;' +
      'window.__pe62("pointerdown",x,y);window.__pe62("pointermove",x-150,y-110);' +
      'var rM=h.getBoundingClientRect();' +
      'window.__pe62("pointercancel",x-150,y-110);' +
      'return {driftX:Math.round(rM.left-r.left),driftY:Math.round(rM.top-r.top),' +
      'dragClassAfter:String(c.className||""),' +
      'spokeAfterCancel:/show/.test(String(b.className||"")),txtAfterCancel:String(b.textContent||"").slice(0,14)};})()'
    );
    // 打断之后立刻点她一下：cancel 若把 suppressPatUntil 也拨上，这一下就被吞掉
    // （计数靠 MutationObserver，回调是异步的 —— 派发那一发里读不到，要等一拍）
    await ctx.client.evaluate(
      '(function(){var sr=document.getElementById("omitone-page-pet-host").shadowRoot;' +
      'sr.getElementById("petImg").dispatchEvent(new MouseEvent("click",{bubbles:true,cancelable:true,view:window}));' +
      'return true;})()'
    );
    await sleep(120);
    var patAfterCancel = await ctx.client.evaluate('window.__pat|0');
    var styleAfterCancel = await ctx.client.evaluate(
      '(function(){var h=document.getElementById("omitone-page-pet-host");' +
      'return {left:Math.round(parseFloat(h.style.left)||0),top:Math.round(parseFloat(h.style.top)||0),' +
      'right:String(h.style.right||""),bottom:String(h.style.bottom||"")};})()'
    );
    check('⑨-a 拖到一半被打断：位置跟着走、dragging 当场摘掉（不许把她丢成"永远在拖"）',
      !!cancelCase && Math.abs(cancelCase.driftX) >= 30 && Math.abs(cancelCase.driftY) >= 20 &&
      !/dragging/.test(cancelCase.dragClassAfter),
      JSON.stringify(cancelCase).slice(0, 240));
    check('⑨-b 打断那一下不说话，而 pointerup 那一路照旧说话（两格各自承重，摘掉任何一半都只红该红那格）',
      !!upControl && upControl.spoke === true && cancelCase.spokeAfterCancel === false,
      JSON.stringify({ up: upControl, cancel: cancelCase }).slice(0, 240));
    // chrome.storage.local.set 是异步的；等它落盘只等"这一发写没写"，不比结果（结果由下面那格判）。
    // 上一发 pointerup 正控也写过一次落点，坐标与这一发不同 —— 等不到就是没写，红给它自己，不会假绿。
    var posStore = null, storedPos = null;
    for (var st62 = 0; st62 < 12; st62++) {
      posStore = await readPopupStore(await initConfigWriter(ctx.extensionId), [POS_KEY]);
      storedPos = (posStore && posStore.val && posStore.val[POS_KEY]) || null;
      if (storedPos && Math.round(storedPos.x) === styleAfterCancel.left &&
          Math.round(storedPos.y) === styleAfterCancel.top) break;
      await sleep(150);
    }
    check('⑨-c 打断那一次的落点进了存档，且存的正是屏幕上那一点（内存／视觉／存档三份读数对得上）',
      !!storedPos && posStore.has[POS_KEY] === true &&
      Math.round(storedPos.x) === styleAfterCancel.left &&
      Math.round(storedPos.y) === styleAfterCancel.top,
      JSON.stringify({ stored: storedPos, style: styleAfterCancel, waited: st62 }).slice(0, 240));
    check('⑨-d 打断不等于"刚拖完"：这一下之后摸头仍然要响应（suppressPatUntil 只归 pointerup 连带的那发 click）',
      patAfterCancel > patBeforeCancel,
      JSON.stringify({ before: patBeforeCancel, after: patAfterCancel }).slice(0, 200));

    // 刷新一次才是用户看得见的那一下：重载时内容脚本按存档落点（content.js:3073 那一族）
    await ctx.client.send('Page.reload', { ignoreCache: false });
    var reloaded = null;
    for (var rw62 = 0; rw62 < 24; rw62++) {
      await sleep(250);
      reloaded = await ctx.client.evaluate(
        '(function(){var h=document.getElementById("omitone-page-pet-host");' +
        'if(!h||!h.shadowRoot||!h.shadowRoot.getElementById("card"))return null;' +
        'var r=h.getBoundingClientRect();' +
        'return {left:Math.round(r.left),top:Math.round(r.top),anchored:(h.style.left||"")===""};})()'
      );
      if (reloaded) break;
    }
    check('⑨-e 刷新一次她不再弹回默认锚点：重载后的落点就是存档那一点（±2px）',
      !!reloaded && !!storedPos && reloaded.anchored === false &&
      Math.abs(reloaded.left - Math.round(storedPos.x)) <= 2 &&
      Math.abs(reloaded.top - Math.round(storedPos.y)) <= 2,
      JSON.stringify({ after: reloaded, stored: storedPos, drift: cancelCase.driftX }).slice(0, 240));

    // 存档与 inline 落点都是本场景自己写的，跑完收干净，别把位置脏留给后面的宠物场景（§5 共享状态）
    await ctx.client.evaluate(
      '(function(){var h=document.getElementById("omitone-page-pet-host");' +
      'h.style.left="";h.style.top="";h.style.right="84px";h.style.bottom="176px";return true;})()'
    );
    await (await initConfigWriter(ctx.extensionId)).evaluate(
      'new Promise(function (res) { chrome.storage.local.remove(' + JSON.stringify([POS_KEY]) +
      ', function () { res(true); }); })'
    );
    var posCleared = await readPopupStore(await initConfigWriter(ctx.extensionId), [POS_KEY]);
    check('⑨-f 场景自己把写过的落点存档收干净（下一枚宠物页回到默认锚点）',
      !!posCleared && posCleared.has[POS_KEY] === false,
      JSON.stringify(posCleared).slice(0, 200));
  }
});

// ── 前端专项：刷课页她自己动（随机换装 / 自动小动作 / 悬停期摸头不被吃掉）─────
// 用户 2026-11-15 点单两件事：「顺便随机一下刷课吉祥物的服装和动作」和「竟然已经不能交互了」。
// 后者根因在 CSS 特异度 —— `.card.peek .pet`(0,3,0) 把 `.pet.pat`(0,2,0) **整条吃掉**：
// 鼠标停在她身上时摸头，动画根本不跑（她那身还歪着，但一帧都没动）。
// ⚠️ 沙盒旧断言只读 class —— `img.click()` 之后 `.pat` 确实挂上了，于是"不能交互"绿了好几轮。
// 判据：**读 computed animationName**。用户看得见的是她在动，不是那个类名。
SCENARIOS.push({
  name: '刷课页她自己动：随机换装不抖、自动小动作四道闸、悬停期摸头动画不被吃掉',
  path: '/quiz',
  run: async function (ctx) {
    await ctx.client.send('Page.bringToFront').catch(function () {});
    var mount = null;
    for (var i = 0; i < 24; i++) {
      await sleep(250);
      mount = await ctx.client.evaluate(
        '(function(){var h=document.getElementById("omitone-page-pet-host");' +
        'if(!h||!h.shadowRoot)return null;var img=h.shadowRoot.getElementById("petImg");' +
        'return {img:!!img,outfit:String(h.dataset.outfit||""),' +
        'src:img?String(img.getAttribute("src")||""):""};})()'
      );
      if (mount && mount.img && mount.outfit) break;
    }
    check('一上线就是随机一身（不再每次都从默认那张开始）',
      !!mount && mount.img === true && /\.png$/.test(mount.outfit) && mount.src.indexOf(mount.outfit) >= 0,
      JSON.stringify(mount));

    // 换装 8 拍：每拍都必须换**另一身** —— 44 张里连续撞同一身并不稀罕，
    // 而用户读到的却是"点了没反应"。断的是换出来的那个名字，不是"有没有监听器"。
    var shots = await ctx.client.evaluate(
      '(function(){var h=document.getElementById("omitone-page-pet-host");var img=h.shadowRoot.getElementById("petImg");' +
      'var seen=[];for(var k=0;k<8;k++){h.dispatchEvent(new Event("omitone:pet-outfit-tick"));seen.push(String(h.dataset.outfit||""));}' +
      'var distinct=[],same=0;' +
      'for(var a=0;a<seen.length;a++){if(distinct.indexOf(seen[a])<0)distinct.push(seen[a]);if(a&&seen[a]===seen[a-1])same++;}' +
      'return {seen:seen,distinct:distinct.length,same:same,' +
      'srcOk:String(img.getAttribute("src")||"").indexOf(seen[seen.length-1])>=0};})()'
    );
    check('连拍 8 次每拍都换了一身（无连续同装、img 的 src 跟着换）',
      !!shots && shots.same === 0 && shots.distinct >= 3 && shots.srcOk === true,
      JSON.stringify(shots).slice(0, 200));

    // 换上的那一身必须真加载得出来（文件在包里 + web_accessible_resources 覆盖到）
    var loaded = await ctx.client.evaluate(
      '(function(){var h=document.getElementById("omitone-page-pet-host");var img=h.shadowRoot.getElementById("petImg");' +
      'return new Promise(function(res){var t0=Date.now();(function poll(){' +
      'if(img.complete&&img.naturalWidth>0)return res({ok:true,src:String(img.getAttribute("src")||"").split("/").pop()});' +
      'if(Date.now()-t0>4000)return res({ok:false,outfit:String(h.dataset.outfit||""),src:String(img.getAttribute("src")||"")});' +
      'setTimeout(poll,80);})();});})()'
    );
    check('换上的这一身真的加载出来了（在包里且 web_accessible 生效）',
      !!loaded && loaded.ok === true, JSON.stringify(loaded));

    // 换装不许把她抖走（用户说的"位置乱了"就来自这里）：44 张原图宽 107~217 各不相同，
    // 渲染盒必须**一张都不差**。⚠️ 先自证"这几张原图宽确实不同"，否则这条量的是空气。
    var measureBox = '(function(){var h=document.getElementById("omitone-page-pet-host");var sr=h.shadowRoot;' +
      'var img=sr.getElementById("petImg"),card=sr.getElementById("card");' +
      'var ir=img.getBoundingClientRect(),cr=card.getBoundingClientRect();' +
      'return {ready:img.complete&&img.naturalWidth>0,nat:img.naturalWidth,outfit:String(h.dataset.outfit||""),' +
      'iw:Math.round(ir.width),ih:Math.round(ir.height),cw:Math.round(cr.width),ch:Math.round(cr.height)};})()';
    var rounds = [], natW = {};
    for (var g = 0; g < 8 && Object.keys(natW).length < 3; g++) {
      await ctx.client.evaluate(
        '(function(){document.getElementById("omitone-page-pet-host").dispatchEvent(new Event("omitone:pet-outfit-tick"));return true;})()');
      var box = null;
      for (var t = 0; t < 40; t++) {
        box = await ctx.client.evaluate(measureBox);
        if (box && box.ready) break;
        await sleep(80);
      }
      if (!box || !box.ready) break;
      rounds.push(box);
      natW[box.nat] = true;
    }
    var sameBox = rounds.length >= 2 && rounds.every(function (b) {
      return b.iw === rounds[0].iw && b.ih === rounds[0].ih
        && b.cw === rounds[0].cw && b.ch === rounds[0].ch;
    });
    check('换装不抖：' + Object.keys(natW).length + ' 张原图宽度不同（' + Object.keys(natW).join('/') +
      '）而渲染盒一模一样（定宽定高 + object-fit 钉住了）',
      Object.keys(natW).length >= 2 && sameBox === true && rounds[0].iw > 0,
      JSON.stringify(rounds.slice(0, 4)).slice(0, 260));

    // ── 她自己动一下 ────────────────────────────────────────────────────────
    // 自动动作与自动台词共用那四道"别说"（看不见 / 被收起 / 正被拖着 / 上一拍还没演完）。
    // ⚠️ 每条"她没动"之前都要先把**别的门槛拨到该动**再拍一下（正例必须动），
    //   否则测到的是门槛串联、不是这一道闸 —— 上一批 ⑥ 同一课。
    var tickMotion = '(function(){var h=document.getElementById("omitone-page-pet-host");var sr=h.shadowRoot;' +
      'var img=sr.getElementById("petImg");' +
      'h.dataset.motion="";img.classList.remove("mv-tilt","mv-hop","mv-spin","mv-wiggle","mv-stretch");' +
      'h.dispatchEvent(new Event("omitone:pet-motion-tick"));' +
      'var name=String(h.dataset.motion||"");' +
      'return {name:name,skip:String(h.dataset.motionSkip||""),cls:String(img.className||""),' +
      'anim:name?getComputedStyle(img).animationName:"",' +
      'rm:!!(window.matchMedia&&window.matchMedia("(prefers-reduced-motion: reduce)").matches),' +
      'hidden:document.hidden};})()';
    await sleep(1800);
    var spoke = await ctx.client.evaluate(tickMotion);
    check('前提：拍一拍她自己动一下（动作名挂上 class，computed 动画跟着来；归因格说"没被挡"）',
      !!spoke && spoke.rm === false && spoke.hidden === false && spoke.skip === ''
      && spoke.name.length > 0
      && spoke.cls.indexOf('mv-' + spoke.name) >= 0 && spoke.anim === 'om-pet-' + spoke.name,
      JSON.stringify(spoke));

    // 上一拍还在演 → 不许叠第二下（叠起来就是用户讨厌的"抽风"）。
    // ⚠️ 两下必须写在**同一次 evaluate** 里：中间不跨任务，时间偷不跑，第二下必然还在 hold 内。
    //   先等她上一拍真演完（读她自己登记的截止时刻，不猜毫秒），否则第一下也动不了。
    var twiceProbe = '(function(){var h=document.getElementById("omitone-page-pet-host");' +
      'if(Number(h.dataset.motionActUntil||0)>Date.now())return {late:true};' +
      'h.dataset.motion="";h.dispatchEvent(new Event("omitone:pet-motion-tick"));' +
      'var first=String(h.dataset.motion||""),firstAt=String(h.dataset.motionAt||"");' +
      'h.dataset.motion="";h.dispatchEvent(new Event("omitone:pet-motion-tick"));' +
      'return {late:false,first:first,firstAt:firstAt,second:String(h.dataset.motion||""),' +
      'secondAt:String(h.dataset.motionAt||""),skip:String(h.dataset.motionSkip||"")};})()';
    var twice = { late: true };
    for (var tw = 0; tw < 40 && twice.late; tw++) {
      twice = await ctx.client.evaluate(twiceProbe);
      if (twice.late) await sleep(200);
    }
    check('上一拍还没跑完时不叠第二下（连发两下只动第一下，第二下的归因格点名「上一拍未完」）',
      !!twice && twice.late === false && twice.first.length > 0 && twice.skip === 'busy' &&
      twice.second === '' && twice.secondAt === twice.firstAt, JSON.stringify(twice));

    // 每一道闸单独验：先把别的门槛拨到"该动"（等她上一拍演完），关上这一道 → 归因格必须点名这一道；
    // 再开回来 → 照动。少了"点名"这一半，测到的是门槛串联而不是这一道闸（批次 61 的 I5 假绿就是栽在这）。
    // waitFree 只读她登记的截止时刻、不拍她 —— 拍了就等于替她把上一演"续"上，反而永远等不到空档。
    var waitFree = async function () {
      for (var i = 0; i < 40; i++) {
        var f = await ctx.client.evaluate('(function(){var h=document.getElementById("omitone-page-pet-host");' +
          'return {busy:Number(h.dataset.motionActUntil||0)>Date.now()};})()');
        if (!f || !f.busy) return true;
        await sleep(200);
      }
      return false;
    };
    var shutTick = '(function(){var h=document.getElementById("omitone-page-pet-host");' +
      'h.dataset.motion="";h.dispatchEvent(new Event("omitone:pet-motion-tick"));' +
      'return {name:String(h.dataset.motion||""),skip:String(h.dataset.motionSkip||"")};})()';
    var gateTry = async function (onJs, offJs, expectSkip) {
      await ctx.client.evaluate(onJs);
      await waitFree();
      var shut = await ctx.client.evaluate(shutTick);
      await ctx.client.evaluate(offJs);
      await waitFree();
      var open = await ctx.client.evaluate(tickMotion);
      await sleep(1800);
      return { shut: shut.name, shutSkip: shut.skip, expect: expectSkip,
               open: open.name, openSkip: open.skip, openAnim: open.anim };
    };
    var hideGate = await gateTry(
      '(function(){document.getElementById("omitone-page-pet-host").shadowRoot.getElementById("wrap").classList.add("mode-hidden");return true;})()',
      '(function(){document.getElementById("omitone-page-pet-host").shadowRoot.getElementById("wrap").classList.remove("mode-hidden");return true;})()',
      'hidden');
    var dragGate = await gateTry(
      '(function(){document.getElementById("omitone-page-pet-host").shadowRoot.getElementById("card").classList.add("dragging");return true;})()',
      '(function(){document.getElementById("omitone-page-pet-host").shadowRoot.getElementById("card").classList.remove("dragging");return true;})()',
      'dragging');
    check('被收起时、正被拖着时都不自己动（挡住她的正是这一道闸，不是上一拍；门开回原样又照动）',
      !!hideGate && hideGate.shut === '' && hideGate.shutSkip === hideGate.expect
      && hideGate.openSkip === '' && hideGate.open.length > 0
      && !!dragGate && dragGate.shut === '' && dragGate.shutSkip === dragGate.expect
      && dragGate.openSkip === '' && dragGate.open.length > 0,
      JSON.stringify({ hide: hideGate, drag: dragGate }).slice(0, 240));

    // 悬停期摸头 —— 本轮真正修的那个 bug。不悬停那一次是**对照**：
    // 两次都读同一个 computed 属性，只有"悬停会吃掉动画"修好了，两条才同时为真。
    var hoverPat = await ctx.client.evaluate(
      '(function(){var h=document.getElementById("omitone-page-pet-host");var sr=h.shadowRoot;' +
      'var c=sr.getElementById("card");var img=sr.getElementById("petImg");' +
      'function pe(t){img.dispatchEvent(new PointerEvent(t,{bubbles:false,cancelable:true,composed:true,' +
      'pointerId:11,pointerType:"mouse",clientX:0,clientY:0}));}' +
      'img.classList.remove("pat");void img.offsetWidth;img.click();' +
      'var bare=getComputedStyle(img).animationName;' +
      'pe("pointerleave");pe("pointerenter");' +
      'var peekOn=c.classList.contains("peek");' +
      'img.classList.remove("pat");void img.offsetWidth;img.click();' +
      'var anim=getComputedStyle(img).animationName;pe("pointerleave");' +
      'return {bare:bare,peekOn:peekOn,hover:anim,hoverCls:String(img.className||"")};})()');
    check('悬停期摸头她照样动（peek 不再吃掉 pat 动画；不悬停那次作对照）',
      !!hoverPat && hoverPat.peekOn === true && hoverPat.bare === 'om-pet-pat'
      && hoverPat.hover === 'om-pet-pat' && /pat/.test(hoverPat.hoverCls),
      JSON.stringify(hoverPat).slice(0, 220));

    await sleep(1800);
    var peekMotion = await ctx.client.evaluate(
      '(function(){var h=document.getElementById("omitone-page-pet-host");var sr=h.shadowRoot;' +
      'var c=sr.getElementById("card");var img=sr.getElementById("petImg");' +
      'img.dispatchEvent(new PointerEvent("pointerenter",{bubbles:false,cancelable:true,composed:true,' +
      'pointerId:12,pointerType:"mouse",clientX:0,clientY:0}));' +
      'var peekOn=c.classList.contains("peek");' +
      'h.dataset.motion="";img.classList.remove("mv-tilt","mv-hop","mv-spin","mv-wiggle","mv-stretch");' +
      'h.dispatchEvent(new Event("omitone:pet-motion-tick"));' +
      'var name=String(h.dataset.motion||"");var anim=name?getComputedStyle(img).animationName:"";' +
      'img.dispatchEvent(new PointerEvent("pointerleave",{bubbles:false,cancelable:true,composed:true,' +
      'pointerId:12,pointerType:"mouse",clientX:0,clientY:0}));' +
      'return {peekOn:peekOn,name:name,anim:anim};})()');
    check('悬停期她自己动也不被 peek 吃掉（动画名 = om-pet-<这一拍的动作>）',
      !!peekMotion && peekMotion.peekOn === true && peekMotion.name.length > 0
      && peekMotion.anim === 'om-pet-' + peekMotion.name,
      JSON.stringify(peekMotion));
  }
});

// ── 前端混沌猴：暴力点击找崩点 ──────────────────────────────────────────────
// 单测喂的是"想得到"的操作；真实用户是乱点的。种子化 LCG 保证失败可复现。
// ⚠️ 目标集刻意排除 #modeSwitch（会重载页面杀掉 CDP 会话）与 #start/#stop（会启动刷课流）。
SCENARIOS.push({
  name: '前端混沌猴：随机点击 400 次零未捕获异常、角色仍响应',
  url: 'chrome-extension://{EXT}/popup/popup.html?ui=fancy',
  inject: false,
  run: async function (ctx) {
    // 进门先记下弹窗会写的 5 枚键（present／absent 各记一格）：逢 toggle 就点的混沌猴把开关
    // 状态留在盘上，停在哪儿由种子决定 —— 后面每一个场景拿到的是上一场的随机态（批次 62-D 同一族）。
    // 上一版只记 `config` 与 `omitonePagePetMinimal` 两枚，另外三枚吉祥物开关（聊天／寻医／
    // 网搜）点脏了没人收（批次 177 / 任务 #61）。
    var storageBefore = await readPopupStore(ctx.client, POPUP_STORAGE_KEYS);
    // 观察者只听不写：把「还有谁在往盘上写这 5 枚」读成一个能涨的数。拉长等待不算尺
    // （快机器恒绿、慢机器恒红，AGENTS §5），这里要的是"写入者停了"这个事件层面的证据。
    await armStoreWatcher(ctx.client, POPUP_STORAGE_KEYS);
    var chaos = await ctx.client.evaluate(
      '(function(){' +
      'var errs = [];' +
      'window.addEventListener("error", function (e) { errs.push(String(e.message || e)); });' +
      'var seed = 20261031;' +
      'function rand() { seed = (seed * 1664525 + 1013904223) >>> 0; return seed / 4294967296; }' +
      'var targets = [document.getElementById("mascot")];' +
      'Array.prototype.forEach.call(document.querySelectorAll("#petTools button"), function (b) { targets.push(b); });' +
      'Array.prototype.forEach.call(document.querySelectorAll(".toggle"), function (b) { targets.push(b); });' +
      'targets.push(document.getElementById("petBookClose"));' +
      'targets.push(document.getElementById("imRestorePet"));' +
      'var clicks = 0;' +
      'for (var i = 0; i < 400; i++) {' +
      '  var t = targets[Math.floor(rand() * targets.length)];' +
      '  if (t && t.click) { try { t.click(); clicks++; } catch (e) { errs.push("click: " + e.message); } }' +
      '}' +
      'return {clicks: clicks, errs: errs, mascotAlive: !!document.getElementById("mascot")};})()'
    );
    check('混沌猴 400 次随机点击（角色/工具条/立绘册/折叠）：零未捕获异常、角色仍在',
      !!chaos && chaos.clicks >= 380 && chaos.errs.length === 0 && chaos.mascotAlive === true,
      JSON.stringify(chaos).slice(0, 200));
    // 收尾：混沌之后角色还能正常响应摸头
    var still = await ctx.client.evaluate(
      '(function(){var errs=[];var onerr=function(e){errs.push(String(e.message||e));};' +
      'window.addEventListener("error",onerr);' +
      'var m=document.getElementById("mascot");if(m)m.click();' +
      'window.removeEventListener("error",onerr);' +
      'return {errs:errs,alive:!!m};})()'
    );
    check('混沌之后摸头仍无异常', !!still && still.alive === true && still.errs.length === 0, JSON.stringify(still));
    // 收尾：把这一场点出来的随机态交回去，并读回来证明真交回去了（不是打了句话就算）。
    // ⚠️ 顺序是「先排干 → 再交回 → 再排干 → 再回读」，不是「写完立刻读」：400 发点击里
    // `config` 那一枚走的是后台 `config_patch` 队列（fire-and-forget，8 秒超时），队尾在我们
    // 交回之后才落回来的话，读到的就是随机态 —— 上一版红/不稳就出在这一族（任务 #61）。
    var drainIn = await waitStoreQuiet(ctx.client, 15000, 3);
    var afterChaos = await readPopupStore(ctx.client, POPUP_STORAGE_KEYS);
    var dirty = diffStoreKeys(storageBefore, afterChaos, POPUP_STORAGE_KEYS);
    // 前提格：这一场真把某枚键点脏了。0 枚脏 = 下面那句比对是空转（断言"绿"有两种）。
    check('混沌这一场真点脏了弹窗会写的键（交回比对不是空转）',
      dirty.length > 0 && drainIn.drained === true,
      JSON.stringify({ dirty: dirty, drained: drainIn.drained, events: drainIn.n,
        waitedMs: drainIn.waitedMs }).slice(0, 240));
    var handed = await handBackPopupStore(ctx.client, storageBefore, POPUP_STORAGE_KEYS);
    var drainOut = await waitStoreQuiet(ctx.client, 12000, 3);
    var restored = await readPopupStore(ctx.client, POPUP_STORAGE_KEYS);
    var differ = diffStoreKeys(storageBefore, restored, POPUP_STORAGE_KEYS);
    check('混沌收尾把弹窗会写的 5 枚键逐枚交回进门那份（随机态不外溢到后面的场景）',
      differ.length === 0 && drainOut.drained === true,
      JSON.stringify({ differ: differ, drainedOut: drainOut.drained, outEvents: drainOut.n,
        del: handed.del, setKeys: handed.setKeys,
        hasBefore: POPUP_STORAGE_KEYS.map(function (k) { return !!storageBefore.has[k]; }),
        hasAfter: POPUP_STORAGE_KEYS.map(function (k) { return !!restored.has[k]; }) }).slice(0, 260));
    // 迟到写单独占一格：交回之后又等了一次排干再读，读数若被队尾改回去，这里说得出是哪一枚。
    // 「排干了」和「读回来还是那份」是两件事，压成一句就会把"我们没等到"读成"没被写"（§2 #12）。
    var drainAgain = await waitStoreQuiet(ctx.client, 6000, 3);
    var recheck = await readPopupStore(ctx.client, POPUP_STORAGE_KEYS);
    var late = diffStoreKeys(restored, recheck, POPUP_STORAGE_KEYS);
    check('混沌交回之后没有迟到写把随机态又落回来（排干不是自证）',
      late.length === 0 && drainAgain.drained === true,
      JSON.stringify({ late: late, drainedAgain: drainAgain.drained, againEvents: drainAgain.n,
        afterHandback: drainAgain.n > 0 ? 'events-after-handback' : 'quiet' }).slice(0, 240));
  }
});

SCENARIOS.push({
  name: '上课页伴侣暴力：连点 30 次不崩、收起唤回仍正常',
  path: '/quiz',
  // 前提钉住「这一格没人按过」：伴侣宿主建不建由 chrome.storage 的精简键决定，
  // 而混沌猴会点到它。见 `setPagePetMinimal` 头上那段。
  pagePetOn: true,
  run: async function (ctx) {
    var mounted = null;
    // 24s 窗口（48×500ms）：满载机器上整轮跑数小时时，挂载会迟到 —— 6 秒窗在批次 123 的
    // 全量跑里实测翻过一次车（前提红 + 下一段裸读 shadowRoot 抛 TypeError，整场景被记成没跑完）。
    for (var i = 0; i < 48; i++) {
      await sleep(500);
      mounted = await ctx.client.evaluate(
        '(function(){var h=document.getElementById("omitone-page-pet-host");' +
        'return !!(h&&h.shadowRoot&&h.shadowRoot.getElementById("petImg"));})()'
      );
      if (mounted) break;
    }
    check('前提：伴侣已挂载', mounted === true, String(mounted));
    if (mounted !== true) return; // 前提没成立就别往下读 —— 裸读只会把「没挂上」变成「页面抛异常」
    var brute = await ctx.client.evaluate(
      '(function(){var h=document.getElementById("omitone-page-pet-host");' +
      'var img=h.shadowRoot.getElementById("petImg");' +
      'var errs=[];window.addEventListener("error",function(e){errs.push(String(e.message||e));});' +
      'for(var i=0;i<30;i++) img.click();' +
      'var bar=h.shadowRoot.getElementById("bondBar").style.width;' +
      'var wrap=h.shadowRoot.getElementById("wrap");' +
      'h.shadowRoot.getElementById("hideBtn").click();' +
      'var hid=/mode-hidden/.test(wrap.className);' +
      'h.shadowRoot.getElementById("pillBtn").click();' +
      'var back=!/mode-hidden/.test(wrap.className);' +
      'return {bar:String(bar||""),hid:hid,back:back,errs:errs,alive:!!h.shadowRoot.getElementById("petImg")};})()'
    );
    check('伴侣连点 30 次：好感条有值、零异常、收起唤回正常',
      !!brute && brute.alive === true && brute.bar !== '' && brute.hid === true && brute.back === true && brute.errs.length === 0,
      JSON.stringify(brute));
  }
});

// ── 上课页本地医生（批次 130）：真实浏览器里才暴露的那三件事 ──────────────────
// 集成层那 29 格（tools/integration-test.js 的 testLocalDoctor）喂的是**打桩**的伴侣，
// 它量不到装机时才看得见的东西：
//   ① `libs/diagnose.js` 真进了 manifest 的 content_scripts —— 漏了的话判断层在页面世界里
//      根本不存在，医生永远只交一句「no-diagnose」，一条测试都不会红；
//   ② 医生装那张 png 真在 web_accessible_resources 里 —— 不在的话 <img> 加载失败、
//      naturalWidth 恒 0，用户看到的是一只空相框；
//   ③ 弹窗那枚开关写进存储的是 1 / 0，content 侧认的必须是同一族（§2 #23 读写两侧基准不同）。
// ⚠️ needle、结论标题、装的文件名与道具、存储键、节流窗口**全部从真源读回来**，
//   这份文件里不抄第二份（§5「断言里出现的每一个数，都要说得出它是从哪儿读回来的」）。
var DOC_TRUTH = (function () {
  var dx = String(fs.readFileSync(path.join(ROOT, 'libs/diagnose.js'), 'utf8'));
  var cg = String(fs.readFileSync(path.join(ROOT, 'content.js'), 'utf8'));
  var pg = String(fs.readFileSync(path.join(ROOT, 'popup/pet-game.js'), 'utf8'));
  function rule(code) {
    var from = dx.indexOf('var RULES = [');
    var at = from < 0 ? -1 : dx.indexOf("code: '" + code + "'", from);
    if (at < 0) return null;
    var seg = dx.slice(at, dx.indexOf('\n    },', at));
    return {
      needle: (seg.match(/needles:\s*\[\s*'([^']+)'/) || [])[1] || '',
      title: (seg.match(/title:\s*'([^']+)'/) || [])[1] || '',
      severity: Number((seg.match(/severity:\s*(\d+)/) || [])[1])
    };
  }
  return {
    media: rule('media-dead'),
    stuck: rule('stuck'),
    key: (cg.match(/PAGE_DOCTOR_KEY\s*=\s*'([^']+)'/) || [])[1] || '',
    prefix: (cg.match(/\('diagnose',\s*'([^']+)'\s*\+/) || [])[1] || '',
    throttle: Number((cg.match(/DOCTOR_ANALYZE_MS\s*=\s*(\d+)/) || [])[1]),
    file: (pg.match(/doctor:\s*\{\s*name:[^,]+,\s*file:\s*'([^']+)'/) || [])[1] || '',
    prop: (pg.match(/doctor:\s*\{\s*name:[^,]+,\s*file:[^,]+,\s*prop:\s*'([^']+)'/) || [])[1] || ''
  };
})();

SCENARIOS.push({
  name: '上课页本地医生：开关关掉不吭声、医生装真加载、结论有界一句、20 秒内不判第二次',
  path: '/quiz',
  // 伴侣宿主建不建由精简键决定（见 setPagePetMinimal 头上那段）
  pagePetOn: true,
  // ⚠️ 这一场吃的是「一页只判一次」那 20 秒窗口：页面自己跑起来会先占掉那一发
  //   （§5 xxtRunning 那条 —— 跑过 run 的场景会让每页加载都自动续跑），必须先按掉。
  noAutoResume: true,
  run: async function (ctx) {
    var T = DOC_TRUTH;
    var truthOk = !!T.media && !!T.stuck && T.media.severity >= 2 && T.media.needle.length > 0 &&
      T.media.title.length > 0 && T.stuck.needle.length > 0 && T.stuck.needle !== T.media.needle &&
      T.key.length > 0 && T.prefix.length > 0 && T.throttle > 0 && T.file.length > 0 && T.prop.length > 0;
    check('夹具自证：这一场的 needle、结论标题、医生装文件名与道具、存储键、节流窗口都从真源读回来了，' +
      '且挑的那条规则够硬（severity 至少 2 才轮到她开口）—— 真源改了名时这条先红，' +
      '后面任何一条红才只能读成「没跑到」',
      truthOk, JSON.stringify(T));
    if (!truthOk) return;

    var DOCTOR_READ = '(function(){var h=document.getElementById("omitone-page-pet-host");' +
      'var sr=h&&h.shadowRoot,img=sr&&sr.getElementById("petImg"),bub=sr&&sr.getElementById("bubble"),' +
      'rp=sr&&sr.getElementById("roleProp"),wrap=sr&&sr.getElementById("wrap");' +
      'if(!img||!bub)return {gone:true};' +
      'return {gone:false,skip:String(h.dataset.doctorSkip||""),role:String(h.dataset.role||""),' +
      'roleFile:String(h.dataset.roleFile||""),src:String(img.getAttribute("src")||""),' +
      'natW:Number(img.naturalWidth||0),shown:bub.classList.contains("show"),' +
      'bubble:String(bub.textContent||""),sayFrom:String(h.dataset.sayFrom||""),' +
      'sayLine:String(h.dataset.sayLine||""),prop:String(rp&&rp.textContent||""),' +
      'tuck:!!(wrap&&wrap.classList.contains("mode-hidden")),hidden:document.hidden,' +
      'ready:document.readyState};})()';
    // 挂载 / 重新加载后的等待：沿用伴侣那场 48×500ms 的窗口（满载机器上挂载会迟到）
    async function waitDoctor() {
      for (var i = 0; i < 48; i++) {
        await sleep(500);
        var r = await ctx.client.evaluate(DOCTOR_READ);
        if (r && r.gone === false && r.ready === 'complete') return r;
      }
      return null;
    }
    // 发一条真日志进这一页的环（走的就是 content.js 收 runtime_log 那一路，不是另开一个口子）。
    // 「还不知道」那一格**不消耗节流**（doctorNote 在按判断地板之前就 return 了），所以可以放心重试。
    async function emitDoctor(needle) {
      var last = null;
      for (var i = 0; i < 4; i++) {
        await ctx.client.evaluate('(function(){window.postMessage({source:"xxt_app",type:"runtime_log",' +
          'level:"warn",message:' + JSON.stringify(needle) + ',meta:null},"*");return true;})()');
        await sleep(220);
        last = await ctx.client.evaluate(DOCTOR_READ);
        if (!last || last.skip !== 'switch-unknown') return last;
      }
      return last;
    }
    // 开关写的是弹窗那侧的字面形状（1 / 0），键名从 content.js 读回来
    async function setDoctor(value) {
      var cw = await initConfigWriter(ctx.extensionId);
      await cw.evaluate('new Promise(function (res) { chrome.storage.local.set(' +
        JSON.stringify({ k: value }).replace('"k"', JSON.stringify(T.key)) +
        ', function () { res(true); }); })');
    }

    // ── ① 开关关掉：一条硬伤进来，她一个字都不多说、一身都不换 ──────────────
    // ⚠️ ②③ 吃的是「没 Key 走本地结论」那条路 —— 配置整轮共用（quiz 场景留下的
    //   `config` 对象带着 Key + 假模型地址），医生会真去问假模型，而假模型对不可解析的
    //   提示词回 '[]'，气泡就成了「体检：[]」（§5 夹具必须自己钉住它依赖的共享状态）。
    //   配置真源是存储里那一枚 `config` 对象（content.js 经 storage.onChanged 现场重读），
    //   清成空对象就是"没 Key"的出厂状态 —— 写顶层散键没人读，等于什么都没钉。
    await writeConfig(ctx.extensionId, {});
    await setDoctor(0);
    var b0 = await waitDoctor();
    check('前提：开关按成关掉之后伴侣照旧挂载（她的出现与这枚开关无关）',
      !!b0 && b0.gone === false, JSON.stringify(b0));
    if (!b0) return;
    await sleep(1200);                       // 让装机期可能自己冒出来的日志先走完
    var off = await emitDoctor(T.media.needle);
    check('① 开关关掉时「' + T.media.needle + '」这一条她一个字都没多说：归因格点名 switch-off' +
      '（弹窗写的 0 必须被认成关掉，认不出的话这句会直接开口）、没换医生装、气泡里没有那一句体检 —— ' +
      '静音不等于忘记：这一条日志照旧进了这一页的环',
      off.skip === 'switch-off' && off.role !== 'doctor' && off.roleFile === '' &&
        off.bubble.indexOf(T.prefix) === -1 && off.sayFrom !== 'diagnose',
      JSON.stringify({ off: off }));

    // ── ② 开关打开：真判断 → 真换装（图必须真加载）→ 有界一句话 ──────────────
    await setDoctor(1);
    await ctx.client.evaluate('(function(){location.reload();return true;})()');
    var b1 = await waitDoctor();
    check('前提：开关打开后重新加载这一页，伴侣回来了（节流是按一页计的，重开一次才拿到干净窗口）',
      !!b1 && b1.gone === false, JSON.stringify(b1));
    if (!b1) return;
    await sleep(1200);
    var pre = await ctx.client.evaluate(DOCTOR_READ);
    check('前提：这一页到目前为止医生还没替她说过话、也没被谁先占掉判断窗口' +
      '（占了的话下面读到的是别人的账，那一格的"没说"根本不是开关造成的）',
      pre.hidden === false && pre.tuck === false && pre.sayFrom !== 'diagnose' &&
        pre.skip !== 'throttle',
      JSON.stringify(pre));
    if (pre.sayFrom === 'diagnose' || pre.skip === 'throttle') return;
    var tOn = Date.now();
    var on = await emitDoctor(T.media.needle);
    var wantLine = T.prefix + T.media.title;
    var wantSrc = 'chrome-extension://' + ctx.extensionId + '/popup/' + T.file;
    check('② 同一句硬伤在开关打开后让她：换上医生装（文件名读自 ROLES.doctor=' + T.file + '）、' +
      '那张图 naturalWidth>0（png 真在 web_accessible_resources 里，否则这里是一只空相框）、道具显影、' +
      '气泡正好是「' + wantLine + '」这一句且长度没被 60 字上限咬掉、归因格记到 diagnose、' +
      '「为什么没说」那一格擦干净',
      on.skip === '' && on.role === 'doctor' && on.roleFile === T.file && on.src === wantSrc &&
        on.natW > 0 && on.prop === T.prop && on.shown === true && on.bubble === wantLine &&
        on.bubble.length === wantLine.length && on.sayFrom === 'diagnose' && on.sayLine === wantLine,
      JSON.stringify({ want: wantLine, wantSrc: wantSrc, on: on }));

    // ── ③ 20 秒内的第二条：不再判第二次 ──────────────────────────────────
    var elapsed = Date.now() - tOn;
    var second = await emitDoctor(T.stuck.needle);
    check('③ 第二次特意换一枚**同等级、不同码**的硬伤（' + T.stuck.needle + '）来测：' +
      elapsed + ' 毫秒 < DOCTOR_ANALYZE_MS（读回来 = ' + T.throttle + '）时她不再判第二次，' +
      '归因格点名 throttle、气泡里还是第一句、行头没动 —— ' +
      '挑同码会被「同一个结论 5 分钟只打扰一次」那把冷却闸挡住，那一轮就成了自证式假绿',
      elapsed < T.throttle && second.skip === 'throttle' && second.sayFrom === 'diagnose' &&
        second.sayLine === wantLine && second.role === 'doctor',
      JSON.stringify({ elapsed: elapsed, throttle: T.throttle, second: second }));

    // ── ③-bis 模型回的不是人话时退回本地结论（反向验证 content.js 的 ask-shape 闸）──
    // 假模型对不可解析的提示词回的是字面 '[]'；没有那道闸时气泡会把「体检：[]」原样说出来。
    // ⚠️ 配置要写进存储里那一枚 `config` 对象（writeConfig 的写法）—— 写顶层散键没人读，
    //   这一发根本不出门，摘掉闸也照样绿（§5：注入必须改到真实状态，本格由此而来）。
    await writeConfig(ctx.extensionId, { apiType: 'openai', apiUrl: 'http://127.0.0.1:' + PORT, apiKey: 'e2e-key', model: 'e2e-model' });
    await ctx.client.evaluate('(function(){location.reload();return true;})()');
    var b3 = await waitDoctor();
    check('前提：配了 Key 重新加载后伴侣照旧挂载（③-bis 的开口要走一次真模型请求）',
      !!b3 && b3.gone === false, JSON.stringify(b3));
    if (!b3) return;
    await sleep(1200);
    var askBefore = ctx.mock.requests.length;
    var junk = await emitDoctor(T.media.needle);
    var asked = ctx.mock.requests.length - askBefore;
    check('前提：③-bis 这一发真去问了模型（mock 台账 +1，实得 ' + asked + ' 发）—— ' +
      '没出门的话后面的绿全是假的（§5：注入必须改到真实状态）',
      asked >= 1, JSON.stringify({ asked: asked }));
    if (asked < 1) return;
    check('③-bis 模型回了一句 JSON（假模型对医生的摘要回字面 \'[]\'）时她退回本地结论：' +
      '气泡仍是「' + wantLine + '」而不是「' + T.prefix + '[]」、归因格记 diagnose、「为什么没说」擦干净、' +
      '医生装没脱 —— 这道闸挡的是「网关回什么就照念什么」那一族，不是把模型的话整个不认',
      junk.sayFrom === 'diagnose' && junk.bubble === wantLine && junk.sayLine === wantLine &&
        junk.skip === '' && junk.role === 'doctor',
      JSON.stringify({ want: wantLine, got: junk }));

    // ── ④ 她被收起来时不换装也不开口（再重开一页拿干净的判断窗口）──────────
    await ctx.client.evaluate('(function(){location.reload();return true;})()');
    var b2 = await waitDoctor();
    check('前提：第二次重新加载后伴侣回来了', !!b2 && b2.gone === false, JSON.stringify(b2));
    if (!b2) return;
    var tuck = await ctx.client.evaluate(
      '(function(){var sr=document.getElementById("omitone-page-pet-host").shadowRoot;' +
      'var w=sr.getElementById("wrap");w.classList.add("mode-hidden");' +
      'return {on:w.classList.contains("mode-hidden")};})()');
    await sleep(600);
    var hid = await emitDoctor(T.media.needle);
    check('④ 她被收起来时医生**既不换装也不开口**，归因格点名 hidden（不是 throttle、不是 no-pet）；' +
      '收起这一步真落在 wrap 的 class 上。⚠️ 只取这一道"看不见"的闸：后台那一格由集成层与' +
      '宠物那场「真后台」一起管，沙盒里标签可见性不稳（§5），把它抄进来只会让这一场恒红',
      tuck.on === true && hid.tuck === true && hid.skip === 'hidden' && hid.role !== 'doctor' &&
        hid.roleFile === '' && hid.src.indexOf('/popup/' + T.file) === -1 &&
        hid.bubble.indexOf(T.prefix) === -1,
      JSON.stringify({ tuck: tuck, base: b2, hidden: hid }));

    // ── ⑤ 收尾卫生：这一格按回出厂（键缺席=开着），别把状态留给后面的场景 ────
    await ctx.client.evaluate(
      '(function(){var sr=document.getElementById("omitone-page-pet-host").shadowRoot;' +
      'var w=sr.getElementById("wrap");w.classList.remove("mode-hidden");' +
      'return {off:!w.classList.contains("mode-hidden")};})()');
    var cwEnd = await initConfigWriter(ctx.extensionId);
    await cwEnd.evaluate('new Promise(function (res) { chrome.storage.local.remove(' +
      JSON.stringify([T.key, 'config']) + ', function () { res(true); }); })');
    await sleep(250);
    var rest = await ctx.client.evaluate('(function(){var sr=document.getElementById("omitone-page-pet-host").shadowRoot;' +
      'var w=sr.getElementById("wrap");' +
      'return {tuck:w.classList.contains("mode-hidden")};})()');
    var stored = await cwEnd.evaluate('new Promise(function (res) { chrome.storage.local.get(' +
      JSON.stringify([T.key, 'config']) + ', function (r) { res(Object.keys(r || {}).length); }); })');
    check('⑤ 收尾：她被放回原样、医生开关按回出厂（存储里那一格整个不存在 = 默认关着，问模型按量计费的功能不许默认烧钱），' +
      '③-bis 写进去的那枚 `config` 也一起收走 —— 这两枚键是整轮共用的，留着会让后面任何一场读到' +
      '"有 Key"或"她本来就不该说话"（§5 夹具必须自己钉住共享状态）',
      rest.tuck === false && stored === 0, JSON.stringify({ rest: rest, stored: stored }));
  }
});

