    check('诊断报告给出定位线索（hint 非空）', !!parsed.hint, JSON.stringify(parsed.hint));
    check('诊断报告记录了扫描过的文档', Array.isArray(parsed.docs) && parsed.docs.length > 0,
      'docs=' + (parsed.docs ? parsed.docs.length : 'n/a'));
